  "授权后，仅新接收的资料触发自动处理；历史资料仍可在批准范围内作为参考。原文可能发送给所选模型服务并产生费用，具体费用取决于服务商。": "Après autorisation, seuls les contenus nouvellement reçus déclenchent le traitement automatique. Les contenus historiques peuvent toujours servir de référence dans la portée approuvée. Le contenu original peut être envoyé aux services de modèle choisis et entraîner des frais dépendant du fournisseur.",
