  "详情 →": "Détails →",
  "当前范围没有同步凭据。开始采集或添加来源后，上传结果会显示在这里。": "Aucun reçu de synchronisation dans cette plage. Les résultats d'envoi s'affichent ici après avoir démarré la capture ou ajouté une source.",
  "第 {0} 页 · 共 {1} 轮同步": "Page {0} · {1} cycles de synchronisation",
  "耗时": "Durée",
  "包含的来源": "Sources incluses",
  "查看内容 →": "Voir le contenu →",
  "查看本次全部内容（{0} 条）": "Voir tout le contenu de ce cycle ({0} enregistrements)",
  "接收确认与中央识别、索引、整理分别进行。失败重试保留原凭据；内容按当前归档保留策略读取。": "Les reçus sont distincts de la reconnaissance, de l'indexation et du traitement centraux. Les nouvelles tentatives conservent les reçus d'origine ; le contenu suit la politique actuelle de conservation de l'archive.",
  "请选择一条记录查看内容。": "Sélectionnez un enregistrement pour voir son contenu.",
  "{0} · 本次上传内容": "{0} · Contenu envoyé",
