  "内容": "Contenu",
  "此记录仅同步目录信息，未上传正文或原件。": "Cet enregistrement ne synchronise que les métadonnées du répertoire ; aucun contenu ni original n'a été envoyé.",
  "内容已接收，中央仍在处理正文。请稍后刷新。": "Le contenu a été reçu ; le central le traite encore. Actualisez plus tard.",
