  "历史按当前节点与设备统计；传输量包含失败尝试，不等于远端存储占用。待复核项不会被自动重试放行。": "L'historique est limité au nœud et à l'appareil actuels. Les totaux transférés incluent les tentatives échouées et ne représentent pas le stockage distant. Les réessais automatiques ne contournent pas la révision de confidentialité.",
