  "同一设备、同一应用的连续截图归为一段；切换应用或相邻采样超过 5 分钟即分段。范围仅限所选日期，本机与中央按各自保留的记录分组。": "Les captures d'écran consécutives d'un même appareil et d'une même app forment une session. Changer d'app ou un écart de plus de 5 minutes démarre une nouvelle session. Les groupes utilisent les enregistrements conservés dans la date sélectionnée.",
