  "填写指向本服务的 HTTPS 地址，供客户端配对和上传使用。二维码不会自动打通网络。": "Saisissez l'adresse HTTPS accessible de ce serveur pour l'appairage et les envois. Un code QR n'établit pas la connectivité réseau.",
  "连接名称": "Nom de la connexion",
  "我的 K90 Pro Max / 工作电脑 / Chatbot": "Mon K90 Pro Max / Ordinateur de travail / Chatbot",
  "用于在下面的列表中识别和撤销连接。": "Permet d'identifier et de révoquer cette connexion dans la liste ci-dessous.",
  "当前是本机地址，手机扫码后会指向手机自己。跨设备连接请先填入可访问的 HTTPS 域名；本机地址可用于同一台电脑或明确配置了端口转发的开发环境。": "Il s'agit d'une adresse loopback ; le téléphone se connecterait à lui-même. Pour connecter un autre appareil, saisissez un domaine HTTPS accessible. Le loopback convient au même ordinateur ou à un environnement de développement avec redirection de port explicitement configurée.",
  "连接类型": "Type de connexion",
