  "Android 可以直接扫码；Mac 可以导入二维码图片。两端均支持粘贴邀请或导入 JSON 文件，确认节点地址后连接。": "Android peut scanner directement ; Mac peut importer une image QR. Les deux permettent de coller une invitation ou d'importer un JSON, puis de confirmer l'URL du nœud.",
  "有效期内，持有邀请的人可以领取该连接。请勿公开分享；关闭此页面不会取消邀请，需使用下面的取消按钮。": "Toute personne détenant une invitation non expirée peut l'utiliser. Ne la partagez pas publiquement. Fermer cette page ne l'annule pas ; utilisez le bouton Annuler ci-dessous.",
