  "加密后续保存的图片和原件": "Chiffrer les images et originaux nouvellement enregistrés",
  "开关立即生效，已有文件保持原格式并可继续读取。记录正文和索引存储在 SQLite 中；客户端的本地存储可在各自开发者选项中设置。": "S'applique immédiatement. Les fichiers existants conservent leur format et restent lisibles. Le texte des enregistrements et les index sont stockés dans SQLite. Configurez le stockage des clients dans leurs options développeur.",
  "一次性批量解密": "Déchiffrer les fichiers existants",
  "取消解密": "Annuler le déchiffrement",
  "关闭上方加密后，可将已有图片、原件和待上传分片逐项转换为明文。任务在后台运行，离开页面仍会继续；取消后保留已完成结果，可再次运行。连接凭据不参与转换。": "Désactivez le chiffrement ci-dessus pour convertir en clair, en arrière-plan, les images, originaux et fragments d'envoi en attente existants. Quitter cette page ne l'arrête pas. L'annulation conserve les résultats obtenus ; relancez pour continuer. Les identifiants de connexion sont exclus.",
