  "聊天图片仅支持 PNG、JPEG、WebP，每张不超过 8 MiB。": "Les images du chat doivent être en PNG, JPEG ou WebP et ne pas dépasser 8 Mio chacune.",
  "聊天图片最多 4 张，每张不超过 8 MiB，支持 PNG、JPEG、WebP。": "Jusqu'à 4 images de chat, chacune de 8 Mio maximum. PNG, JPEG et WebP sont pris en charge.",
