  "你的设备": "Vos appareils",
  "采集在设备本机运行，同步按每台设备的偏好进行。": "La collecte s'exécute localement sur chaque appareil ; la synchronisation suit les préférences de chacun.",
  "扫码连接设备": "Scanner pour connecter un appareil",
  "这里显示设备最近一次上报。较久未联系可能是定时、手动同步或网络变化，不能据此判断本机是否正在采集。": "Affiche le dernier rapport de chaque appareil. Un long intervalle peut refléter une synchronisation planifiée ou manuelle, ou des changements réseau ; cela n'indique pas si la collecte locale est en cours.",
  "从你的第一台设备开始": "Commencez par votre premier appareil",
  "生成一次性邀请，在手机或 Mac 的连接设置中确认。客户端也可以先在本机记录，稍后再连接。": "Générez une invitation à usage unique et confirmez-la dans les paramètres de connexion de votre téléphone ou Mac. Les clients peuvent collecter localement avant de se connecter.",
