  "系统调度、网络与电量条件可能推迟。": "La planification du système, le réseau et la batterie peuvent la retarder.",
  "此客户端尚未上报同步策略。采集与同步偏好请在客户端设置。": "Ce client n'a pas rapporté de politique de synchronisation. Configurez la collecte et la synchronisation sur le client.",
