  "已复制当前页日志。": "La page de journal actuelle a été copiée.",
  "剪贴板不可用，已全选，请按 ⌘/Ctrl+C 复制。": "Presse-papiers indisponible. Le texte est sélectionné ; appuyez sur ⌘/Ctrl+C pour copier.",
