  "诊断包包含运行状态、数量、耗时和最近事件，不包含笔记、截图、模型对话或访问令牌。客户端的采集、电量和本地队列诊断从各自 App 导出。": "Contient l'état d'exécution, les comptages, les durées et les événements récents ; exclut les notes, captures d'écran, conversations de modèle et jetons. Exportez les diagnostics de collecte, de batterie et de file locale des clients depuis chaque app.",
