  "默认从当前日志的最新一页开始；翻页查看更早内容，刷新时不会离开当前页。可按阶段筛选，日志仍按原始顺序显示，不拆字段或重排。": "S'ouvre sur la dernière page du journal actuel. Changez de page pour voir des entrées plus anciennes ; l'actualisation conserve la page. Filtrez par étape tout en gardant les lignes dans leur ordre d'origine, sans restructuration.",
