  "全部来源": "Toutes les sources",
  "中央文件处理设置": "Traitement central des fichiers",
  "按文件类型选择处理方案。服务保存地址和密钥；方案保存独立参数；同一目录可对录音和图片采用不同方案。处理均由中央节点调度。": "Choisissez un plan de traitement par type de fichier. Les services conservent les URL et les clés ; les plans gardent des paramètres indépendants. Un même répertoire peut utiliser des plans différents pour l'audio et les images. Le traitement est planifié par le nœud central.",
  "设置已保存。新文件和未完成任务使用新配置；已完成文件保留原结果。": "Paramètres enregistrés. Les nouveaux fichiers et les tâches inachevées utilisent la nouvelle configuration ; les résultats terminés sont conservés.",
  "处理开关与预算": "Traitement et budgets",
  "启用中央文件处理": "Activer le traitement central des fichiers",
  "单次文件处理超时（秒）": "Délai d'appel du traitement de fichier (secondes)",
  "1. 类型策略": "1. Stratégies de types",
  "具体 MIME 类型优先于类型通配符；未配置的格式按“其他”处理。PDF 处理插件可由管理员接入 Cordis，接入后可在此选择。": "Les types MIME exacts priment sur les jokers. Les formats non configurés relèvent de « Autre ». Les administrateurs peuvent intégrer un plugin PDF via Cordis, puis le sélectionner ici.",
