  "添加处理方案": "Ajouter un plan de traitement",
  "3. 来源覆盖": "3. Remplacements par source",
  "仅覆盖选中的来源和文件类型；其他文件继续使用全局类型策略。匹配顺序：来源具体类型 → 来源通配类型 → 全局具体类型 → 全局通配类型 → 其他。": "Ne remplace que les sources et types de fichiers sélectionnés. Les autres utilisent les règles globales. Priorité : type exact de la source → joker de la source → type exact global → joker global → Autre.",
  "来源": "Source",
