  "服务连接": "Connexions de services",
  "地址和密钥只需配置一次。共享服务的方案仍保留各自参数。远程服务需显式选择“远程 HTTPS”；本地多人录音只能绑定本地服务。": "Configurez les URL et les clés une seule fois ; les plans partageant un service gardent des paramètres indépendants. Sélectionnez explicitement « HTTPS distant » pour les services distants. L'audio local à plusieurs locuteurs exige des services locaux.",
