  "以下操作使用已保存设置。仅归档和 Shadow 文件不会进入内容处理；每次最多重新处理 100 份当前版本原件，预览有效期 10 分钟。": "Utilise les paramètres enregistrés. Les fichiers en archive uniquement et les fichiers shadow ne sont pas traités. Retraitez jusqu'à 100 originaux de la version actuelle par lot ; les aperçus expirent en 10 minutes.",
