  "移除 ": "Retirer ",
  "中央服务器上的目录": "Répertoire sur le serveur central",
  "这是运行 Mote 中央节点的机器上的路径。节点会复制可读取的文件到归档。": "Un chemin sur la machine qui exécute votre nœud central. Les fichiers lisibles seront copiés dans l'archive.",
  "资料名称": "Nom du matériel",
  "选填": "Facultatif",
  "例如：过去一年的随手记": "Par exemple : les notes rapides de l'année dernière",
  "告诉 Mote 如何理解这份资料": "Indiquez à Mote comment interpréter ce matériel",
  "格式、作者与归属说明": "Indications sur le format, la paternité et l'attribution",
  "格式按所选 Source Pack 解析；说明用于资料背景和归属范围。": "Le Source Pack sélectionné détermine l'analyse du format. Les indications fournissent le contexte du matériel et la portée de l'attribution.",
  "例如：这是我的日记，引用和 AI 回复属于原说话人。时间是北京时间；每篇日记独立保存。": "Par exemple : ce sont mes entrées de journal. Les citations et les réponses IA appartiennent à leurs auteurs d'origine. Les heures sont celles de Pékin ; enregistrez chaque entrée séparément.",
  "可一次说明格式、时间、作者，以及哪些内容属于你。模型按说明范围理解，第三方和 AI 引用保留原角色。": "Expliquez en un seul endroit le format, les heures, les auteurs et ce qui vous appartient. Le modèle suit la portée de vos indications et conserve les rôles d'origine des citations de tiers et d'IA.",
  "未填写也会保留原件，可检索已提取的正文；身份未知时，可保存有用的来源限定观察。": "Sans indications, les originaux sont tout de même conservés et le texte extrait reste recherchable. Quand l'identité est inconnue, des observations utiles peuvent être enregistrées avec leur portée de source.",
  "本次导入说明": "Indications pour cet import",
  "说明按文字中的范围用于理解这次导入的资料，不会把第三方和 AI 引用整批变成你的表达。": "Les indications s'appliquent au matériel de cet import dans leur portée déclarée. Les citations de tiers et d'IA ne deviennent pas vos propres paroles sur l'ensemble du lot.",
  "例如：这是我的聊天导出，张三是我。时间是北京时间；每段对话独立保存，保留消息的时间和附件关系。": "Par exemple : ceci est mon export de chat ; Zhang San, c'est moi. Les heures sont celles de Pékin. Enregistrez chaque conversation séparément, en conservant les horaires des messages et les liens vers les pièces jointes.",
  "可以说明人物、时间、格式和需要保留的细节。含糊之处会出现在预览中。": "Précisez les personnes, les heures, les formats et les détails à conserver. Les ambiguïtés apparaîtront dans l'aperçu.",
  "先保存原件，解析完成后由你确认。": "Les originaux sont d'abord enregistrés. Confirmez après l'analyse.",
