  "屏幕已锁定": "Écran verrouillé",
  "屏幕未锁定": "Écran déverrouillé",
  "仅保留应用与播放状态；标题、作者、专辑等内容不采集。": "Seuls l'application et l'état de lecture sont conservés ; les titres, auteurs et albums sont exclus.",
  "这是应用公开的状态。媒体采集在客户端单独开启；通知使用权用于发现媒体会话，不保存通知正文或音频。音乐、有声书等内容类型由分析时结合证据判断。": "Cet état est publié par l'application. La collecte des médias s'active séparément sur le client. L'accès aux notifications sert à découvrir les sessions médias sans enregistrer le contenu des notifications ni l'audio. Les types de contenu (musique, livres audio, etc.) sont déterminés à partir des preuves lors de l'analyse.",
  "播放应用": "Application de lecture",
