  "在 Android 客户端开启媒体采集并授权，记录同步后会出现在这里。没有记录不代表没有播放。": "Activez et autorisez la collecte des médias sur le client Android. Les enregistrements apparaissent après la synchronisation. L'absence d'enregistrements ne signifie pas qu'il n'y a eu aucune lecture.",
  "媒体播放采样时长": "Durée de lecture échantillonnée",
  "次状态观察": "observations d'état",
