  "次状态不可用。这些观察无法确定是否有播放。": "état indisponible. Ces observations ne permettent pas de déterminer s'il y a eu lecture.",
  "查看 {0} 的媒体证据": "Voir les preuves média de {0}",
  "应用位置": "Visibilité de l'application",
  "前台": "Premier plan",
  "· 后台": "· Arrière-plan",
