  "· 远程": "· À distance",
  "屏幕状态": "État de l'écran",
  "锁定": "Verrouillé",
  "· 未锁定": "· Déverrouillé",
  "按设备查看": "Par appareil",
  "媒体播放与前台应用使用分别计时，可能同时发生，不应相加。只累计独立媒体记录的播放采样区间；同一设备重叠区间合并，多台设备分别累计。应用或状态分组可能重叠。": "La lecture de médias et l'utilisation au premier plan sont mesurées séparément et peuvent se chevaucher ; ne les additionnez pas. Seuls les intervalles échantillonnés de lecture issus d'enregistrements médias indépendants comptent. Les chevauchements sont fusionnés par appareil ; les appareils différents cumulent séparément. Les groupes par application ou par état peuvent se chevaucher.",
  "截图附带的媒体状态不重复计时。暂停、缓冲和观察空隙不补齐；播放进度或媒体总长度不等于收听时长，远程播放也不代表手机发声。": "L'état média joint aux captures n'est pas compté deux fois. Les pauses, la mise en mémoire tampon et les trous d'observation ne sont pas comblés. La position de lecture et la durée du média ne représentent pas la durée d'écoute ; la lecture à distance ne signifie pas que le téléphone a produit du son.",
