  "个片段已处理过或没有可提取的正文，本次未重复处理。原始资料仍可查看。": "segments déjà traités ou sans texte extractible ; ils n'ont pas été retraités. Les originaux restent consultables.",
  "在设置中配置模型后，可从这里继续。": "Configurez un modèle dans les paramètres, puis continuez ici.",
