  "等待下一次检查": "En attente de la prochaine vérification",
  "记忆与洞察的节奏": "Rythme des mémoires et des insights",
  "周期已到，并且新增变化达到门槛时才运行。每分钟检查一次；保存后直接生效，进行中的窗口沿用启动时的设置。": "S'exécute lorsque l'intervalle est échu et que les nouveaux changements atteignent le seuil. Vérification chaque minute. Les modifications enregistrées s'appliquent immédiatement ; les exécutions en cours gardent leurs paramètres de départ.",
  "设置已保存。": "Paramètres enregistrés.",
  "启用自动整理": "Activer la consolidation automatique",
