  "每个窗口最多处理变化": "Changements max par exécution",
  "· 待处理": "· En attente",
  "次变化 · 周期到达时间": "changements · Prochaine échéance",
  " · 已失败 {0} 次，自动退避重试": " · {0} échecs ; réessai avec backoff",
  "每次披露的内容量": "Contenu divulgué par étape",
  "提取批次字符上限": "Limite de caractères par lot d'extraction",
  "至少保留近期对话轮数": "Tours de conversation récents minimum",
  "对话上下文字符上限": "Limite de caractères du contexte de conversation",
  "工作记忆字符上限": "Limite de caractères de la mémoire de travail",
  "记忆以文本保存，按“概览 → 内容与边界 → 原始证据”逐层展开，全文索引可从文本重建。自动生成的长期记忆需要你确认。高频上传建议保留较长周期和每轮上限。": "Les mémoires sont enregistrées en texte et divulguées progressivement : aperçu → contenu et limites → preuves d'origine. Les index plein texte peuvent être reconstruits. Les mémoires à long terme générées automatiquement nécessitent votre confirmation. Pour des envois fréquents, utilisez des intervalles plus longs et des lots limités.",
  "正在保存…": "Enregistrement…",
  "保存记忆设置": "Enregistrer les paramètres de mémoire",
