  "仅显示上报时可获取的字段。状态是当时的观察值；缺失不代表否或零。": "Seuls les champs rapportés disponibles sont affichés. Les valeurs décrivent les observations du moment ; une absence ne signifie ni faux ni zéro.",
  "原始系统事件，不表示你已阅读通知或正在执行某项任务。熄屏不等于锁定；服务中断期间不补造事件。系统可能隐藏敏感通知。": "Les événements système bruts n'établissent pas que vous avez lu une notification ou exécuté une tâche. Écran éteint ne signifie pas verrouillé. Les interruptions ne sont pas reconstruites ; le système peut masquer les notifications sensibles.",
  "文件访问时间也可能由同步程序或其他进程读取更新，不能据此断定你查看过文件。": "Les dates d'accès aux fichiers peuvent être mises à jour par des outils de synchronisation ou d'autres processus et ne prouvent pas que vous avez consulté un fichier.",
  "这是完整扫描发现来源消失的时间，无法确认实际删除时刻或原因，也可能是移动或重命名。": "Une analyse complète a détecté la disparition à cette date ; impossible d'établir quand ni pourquoi la suppression a eu lieu. Le fichier a pu être déplacé ou renommé.",
