  "目录暂无可用模型，可手动填写。": "Aucun modèle dans le catalogue. Saisissez-en un manuellement.",
  "目录使用中央节点本机 Codex 的登录账户。选择只填写模型 ID；实际请求仍使用本页配置的 API 协议与凭据。": "Utilise le compte Codex local de l'hôte central. La sélection ne remplit que l'ID du modèle ; les requêtes utilisent toujours le protocole API et les identifiants configurés ici.",
  "根据当前地址和凭据自动加载；目录可见不代表支持工具调用，可使用下方测试连接验证。": "Chargé automatiquement à partir de l'URL et des identifiants actuels. La visibilité du catalogue ne garantit pas la prise en charge des outils ; utilisez Tester la connexion ci-dessous.",
