  "Agent 总运行超时": "Délai total d'exécution de l'agent",
  "单次模型请求超时须为 5–600 秒。": "Le délai d'une requête de modèle doit être compris entre 5 et 600 secondes.",
  "Agent 总运行超时须为 5–3600 秒。": "Le délai total d'exécution de l'agent doit être compris entre 5 et 3600 secondes.",
  "Agent 总运行超时须为空，或为 5–3600 秒。": "Le délai total d'exécution de l'agent doit être vide ou compris entre 5 et 3600 secondes.",
  "5–600 秒；只限制一次 Provider API 请求，不包含后续工具循环。": "5–600 secondes ; limite une seule requête API au fournisseur et exclut les boucles d'outils ultérieures.",
  "可留空；限制从 Agent 开始到结束的整个运行周期，包含多次模型请求和工具调用。": "Facultatif ; limite l'exécution complète de l'agent du début à la fin, y compris les multiples requêtes de modèle et appels d'outils.",
  "5–3600 秒；限制一次 Agent 从开始到完成的整个运行周期。": "5–3600 secondes ; limite une exécution d'agent du début à la fin.",
  "输出上限 / 超时": "Limite de sortie / Délais",
  "Codex 管理输出；Agent 总运行超时 {0}": "Codex gère la sortie ; délai total d'exécution de l'agent : {0}",
  "单次模型请求 / Agent 总运行超时": "Requête de modèle unique / Délai total d'exécution de l'agent",
  "不适用": "Non applicable",
  "高级设置 · 输出预算": "Avancé · Budget de sortie",
  "输出预算档位": "Préréglage du budget de sortie",
  " · 默认": " · Par défaut",
  "自定义 · 在右侧填写": "Personnalisé · Saisir à droite",
  "常用默认 65,536；选择支持当前预算的模型。": "La valeur par défaut est 65 536. Choisissez un modèle prenant en charge ce budget.",
  "最大输出 token 数": "Nombre maximal de tokens en sortie",
  "输出 token 上限": "Limite de tokens en sortie",
  "1–128000。单次响应的上限，包含正文、HTML 及服务商计入的推理 token，不是固定生成长度、字数或图片大小。保存后生效。": "1–128000. Limite par réponse incluant le texte, le HTML et les tokens de raisonnement comptés par le fournisseur. Ce n'est ni une longueur de réponse fixe, ni un nombre de mots, ni une taille d'image. Appliqué à l'enregistrement.",
  "允许本机模型免密访问": "Autoriser les modèles locaux sans authentification",
  "只适用于回环地址；容器中的“本机”指容器本身。": "Adresses de bouclage uniquement. Dans un conteneur, « local » désigne le conteneur lui-même.",
  "自定义请求头操作": "Action sur les en-têtes personnalisés",
  "自定义请求头 JSON": "JSON des en-têtes personnalisés",
  "名称与值均为字符串；整体替换。已有值不会读取或回显。": "Les noms et valeurs doivent être des chaînes. Remplace l'objet entier ; les valeurs existantes ne sont jamais affichées.",
  "高级请求参数操作": "Action sur les paramètres avancés",
  "高级请求参数 JSON": "JSON des paramètres avancés",
  "按当前协议填写 JSON 对象，整体替换。消息、工具与其他运行必需字段由 Mote 管理；已有值不会回显。": "Saisissez un objet JSON pour le protocole actuel. Remplace l'objet entier. Mote gère les messages, les outils et les champs requis ; les valeurs existantes sont masquées.",
  "允许在更改后的服务地址复用已保存的凭据": "Autoriser la réutilisation des identifiants enregistrés sur l'URL de service modifiée",
  "这会把保留的 API key、请求头或高级参数发送到当前填写的地址。也可以改为填写新值或清除旧值。": "Envoie les clés API, en-têtes ou paramètres avancés conservés vers l'URL saisie. Vous pouvez aussi saisir de nouvelles valeurs ou effacer les anciennes.",
  "测试连接会由中央节点发送少量合成内容，最多等待 30 秒，可能产生少量费用；不会读取资料库。测试不会保存草稿。": "Le test envoie une petite requête synthétique depuis le nœud central, attend jusqu'à 30 secondes et peut engendrer un léger coût. Il ne lit pas l'archive et n'enregistre pas le brouillon.",
  "（{0} 秒）": "({0} secondes)",
  "；保存后才会应用草稿。": "; enregistrez pour appliquer le brouillon.",
  "有未保存的修改，仅保留在当前页面": "Des modifications non enregistrées n'existent que sur cette page",
  "当前没有未保存的修改": "Aucune modification non enregistrée",
  "测试连接": "Tester la connexion",
  "保存并应用": "Enregistrer et appliquer",
  "当前生效模型配置": "Configuration de modèle active",
  "当前生效值": "Valeurs actuelles",
  "来自页面保存的配置；重启中央节点后仍然保留。": "Enregistrée via cette page ; conservée après les redémarrages du nœud.",
  "来自中央节点的启动环境或部署配置。": "Provenant de l'environnement de démarrage ou de la configuration de déploiement.",
  "只读": "Lecture seule",
  "服务": "Service",
  "未设置（问答与模型回顾关闭）": "Non défini (questions et bilans par modèle désactivés)",
  "协议": "Protocole",
  "输出上限 / 等待时间": "Limite de sortie / Délai",
  "{0} tokens / {1} 秒": "{0} tokens / {1} secondes",
  "自定义请求头": "En-têtes personnalisés",
  "高级请求参数": "Paramètres avancés",
  "恢复部署配置": "Restaurer les paramètres de déploiement",
  "删除本页保存的模型配置，立即重新使用中央节点的启动环境或部署配置。当前未保存的草稿也会清空；不会修改部署文件。": "Supprime les paramètres de modèle enregistrés ici et restaure immédiatement les paramètres de démarrage ou de déploiement. Les brouillons non enregistrés sont aussi effacés. Les fichiers de déploiement restent inchangés.",
  "正在恢复…": "Restauration…",
  "确认恢复部署配置": "Confirmer la restauration des paramètres de déploiement",
  "随手记已同步到你的中央节点。": "Note rapide synchronisée avec votre nœud central.",
  "本机存储不可用或已满；草稿目前只在此窗口，请先复制保存。": "Le stockage local est indisponible ou plein. Le brouillon n'existe que dans cette fenêtre ; copiez-le d'abord.",
  "Mote 随手记": "Note rapide Mote",
  "已保存到本机待同步队列，联网后会继续同步。": "Enregistrée dans la file d'attente locale. La synchronisation reprendra une fois connecté.",
  "移除这条本机待同步副本？若中央节点已收到但确认丢失，需要在下方历史记录中另行删除。": "Supprimer cette copie locale en attente de synchronisation ? Si le nœud l'a reçue mais que la confirmation s'est perdue, supprimez l'enregistrement archivé séparément ci-dessous.",
  "想到什么，就记下来。": "Notez les choses au fur et à mesure.",
  "心情、杂事、一个还没成形的想法，都可以成为上下文。": "Humeurs, petites tâches et idées encore floues peuvent tous devenir du contexte.",
  "此刻想留下什么？": "Que souhaitez-vous garder en ce moment ?",
  "记下此刻的想法…": "Notez vos pensées…",
  "我的心情": "Mon humeur",
  "可选，由你自己描述": "Facultatif, dans vos propres mots",
  "比如：松了一口气": "Par exemple : soulagé",
  "草稿已保存在本机 ·": "Brouillon enregistré localement ·",
  "字": "caractères",
  "保存并同步": "Enregistrer et synchroniser",
  "草稿和待同步内容保存在此应用的本机存储中，清除应用数据会移除它们。打开随手记时自动续传；按中央节点地址分别保存。": "Les brouillons et les notes en attente sont stockés localement dans cette application, par URL de nœud central. Effacer les données de l'application les supprime. La synchronisation reprend à l'ouverture des notes rapides.",
