  "空间详情、归档导入与导出": "Détails du stockage, import et export de l'archive",
  "连接授权": "Autorisations de connexion",
  "设备邀请与外部 Chatbot 凭据": "Invitations d'appareils et identifiants de chatbots externes",
  "关于 Mote": "À propos de Mote",
  "软件版本、更新与部署信息": "Version, mises à jour et informations de déploiement",
  "开发者选项": "Options pour les développeurs",
  "诊断、日志与高级生效配置": "Diagnostics, journaux et paramètres avancés actifs",
  "模型与记忆设置可直接保存并生效；其他偏好通过部署草稿修改并重启。离开设置页面或返回上级菜单时，未保存的输入会丢弃。": "Les paramètres de modèle et de mémoire s'appliquent à l'enregistrement. Les autres préférences passent par un brouillon de déploiement et un redémarrage. Les saisies non enregistrées sont perdues en quittant les paramètres ou en revenant au menu parent.",
  "来自运行中的中央节点；与上方尚未应用的草稿分开显示。": "Provenant du nœud central en cours d'exécution ; affiché séparément du brouillon non appliqué ci-dessus.",
  "部署与全部生效配置": "Déploiement et tous les paramètres actifs",
  "进程环境变量": "Variables d'environnement du processus",
  "数据目录": "Répertoire de données",
  "相对路径基准": "Base des chemins relatifs",
  "软件版本与更新": "Version et mises à jour",
  "更新替换程序，保留原环境设置、模型、队列和资料库。": "Les mises à jour remplacent le programme en conservant les paramètres d'environnement, les modèles, les files d'attente et les archives.",
  "正在检查…": "Vérification…",
  "检查新版本": "Rechercher des mises à jour",
  "当前版本": "Version actuelle",
  "正式渠道": "Canal stable",
  "预览渠道": "Canal d'aperçu",
  "点击检查后连接 GitHub，不上传个人资料或中央令牌。": "La vérification se connecte à GitHub sans envoyer de données personnelles ni de jetons centraux.",
  "此渠道暂时没有可用的签名发布版本。": "Aucune version signée disponible sur ce canal pour le moment.",
  "更新检查未通过，现有程序和设置保持原样；稍后可重试。": "La vérification des mises à jour a échoué. Le programme et les paramètres existants restent inchangés. Réessayez plus tard.",
  "发现 {0}，发布签名已验证。": "{0} trouvée ; signature de la version vérifiée.",
  "已是最新版本，发布签名已验证。": "À jour ; signature de version vérifiée.",
  "查看版本说明与安装包": "Voir les notes de version et les téléchargements",
  "上次检查：": "Dernière vérification :",
  "在部署机的 Mote 目录执行。命令先校验下载并准备程序，再备份、切换和检查健康状态。新版启动失败时保留快照，使用回退命令恢复。": "À exécuter dans le répertoire Mote de l'hôte de déploiement. La commande vérifie et prépare le téléchargement, puis sauvegarde, bascule et contrôle la santé. En cas d'échec du démarrage, utilisez la commande de restauration pour rétablir l'instantané conservé.",
  "需要回退时": "Pour revenir en arrière",
  "回退恢复升级前的数据快照；升级后的资料会另行保留。不要直接用旧程序打开已升级的数据。": "La restauration rétablit l'instantané d'avant la mise à jour et conserve les données plus récentes séparément. N'ouvrez pas les données mises à niveau avec une ancienne version du programme.",
  "此节点未由命名部署环境管理。请先按部署文档建立对应环境，再使用更新命令；本页面不会直接重启当前服务。": "Ce nœud n'est pas géré par un profil de déploiement nommé. Créez-en un en suivant la documentation de déploiement avant d'utiliser les commandes de mise à jour. Cette page ne redémarre pas le service.",
