  "快照保存当次文字，引用只保存原件位置。资料后续变化会成为新版本，方便查看来处。": "Les instantanés conservent le texte tel qu'observé ; les références ne gardent que l'emplacement d'origine. Les modifications ultérieures deviennent de nouvelles révisions dont l'origine reste traçable.",
