  "提交文件、ZIP 或服务器目录，先查看解析预览，再确认写入。导入后的资料会显示在来源列表中。": "Soumettez des fichiers, un ZIP ou un répertoire du serveur. Vérifiez l'aperçu d'analyse avant de confirmer. Le matériel importé apparaît dans la liste des sources.",
