  "连接 Google Calendar": "Connecter Google Calendar",
  "由中央节点定时同步你选定的日历，只申请读取权限。取消连接会移除本机授权，历史资料仍保留。": "Le nœud central synchronise périodiquement les calendriers sélectionnés avec un accès en lecture seule. La déconnexion supprime l'autorisation locale tout en conservant l'historique.",
  "请先在设置 → 来源与外部应用中准备 Google OAuth 客户端与回调地址，然后重启节点。": "Préparez d'abord le client Google OAuth et l'URL de rappel dans Paramètres → Sources et applications externes, puis redémarrez le nœud.",
  "账户已连接": "Compte connecté",
  "尚未授权": "Non autorisé",
