  "支持自定义 Bearer 令牌的 Chatbot 可连接本节点的": "Les chatbots prenant en charge des jetons Bearer personnalisés peuvent se connecter au point de terminaison de ce nœud",
  "地址。只读连接可检索资料；写回需单独开启写令牌和允许写入的来源。": ". L'accès en lecture seule permet de rechercher dans l'archive ; l'écriture nécessite un jeton d'écriture distinct et des sources autorisées.",
  "状态：": "État :",
