  "写回已关闭": "Écriture désactivée",
  "。配置入口在“设置 → 来源与外部应用”。仅支持 OAuth 的 Chatbot 不能直接使用 Bearer 接入。": ". Configurez dans Paramètres → Sources et applications externes. Les chatbots limités à OAuth ne peuvent pas se connecter directement avec un jeton Bearer.",
  "从 MCP 服务导入可见资料": "Importer les ressources visibles depuis un service MCP",
  "选择资源后执行一次导入；不会迁移其他 Chatbot 的隐藏记忆，不会自动调用外部写入工具。": "Sélectionnez des ressources pour une importation unique. Les mémoires cachées des chatbots ne sont pas migrées et les outils d'écriture externes ne sont pas appelés automatiquement.",
  "MCP 服务地址": "URL du service MCP",
