  "次费用未估算。缓存率按已上报缓存数据的输入 token 加权；未知部分不按零计算。": "coûts non estimés. Les taux de cache sont pondérés par les tokens d'entrée des données de cache signalées. Les valeurs inconnues ne comptent pas comme zéro.",
  "运行成功率": "Taux de réussite des exécutions",
  "平均耗时": "Durée moyenne",
  "P95 耗时": "Durée P95",
  "已计量模型请求": "Requêtes du modèle mesurées",
  "成功率与耗时仅统计已结束运行；失败运行的已上报消耗仍计入。Skill 指运行入口指定的主流程，每笔消耗只归属一次，不拆分动态调用的子 Skill。": "Les taux de réussite et les durées ne comptent que les exécutions terminées. L'utilisation signalée des exécutions échouées compte toujours. Un skill désigne le flux principal de l'exécution ; chaque coût n'est attribué qu'une fois, sans répartir les sous-skills appelés dynamiquement.",
  "当前日期和筛选条件下没有用量记录。功能启用前的历史对话无法补算。": "Aucun enregistrement d'utilisation ne correspond à ces dates et filtres. Les conversations antérieures ne peuvent pas être mesurées rétroactivement.",
  "每日用量 · 点击日期查看当天": "Utilisation quotidienne · Sélectionnez une date pour les détails",
  "运行": "Exécution",
  "输入 / 输出": "Entrée / Sortie",
  "模型价格与计费设置": "Prix des modèles et paramètres de facturation",
  "填写服务商或你的套餐单价（每百万 tokens）。包括缓存折扣；订阅套餐无法据此推算实际扣费。价格在每次运行开始时固定。": "Saisissez les prix du fournisseur ou de votre forfait par million de tokens, remises de cache incluses. Les frais d'abonnement ne peuvent pas être déduits de ces estimations. Les prix sont fixés au début de chaque exécution.",
