  "次运行，显示最近": "exécutions ; affichage des dernières",
  "次；所有统计覆盖全部符合条件的记录。": ". Les statistiques couvrent tous les enregistrements correspondants.",
  "未知模型": "Modèle inconnu",
  "管理请求必须使用当前服务的 API 路径。": "Les requêtes d'administration doivent utiliser le chemin API de ce service.",
  "入口等待服务响应超时（524）。请检查节点运行诊断；较慢的模型请求可能超过代理等待上限。": "La passerelle a dépassé le délai d'attente du service (524). Consultez les diagnostics du nœud ; les requêtes de modèle lentes peuvent dépasser le délai du proxy.",
  "上传超过中央节点或公网入口的大小限制（413）。可以分批上传，或将文件放到中央服务器后从目录导入。": "L'envoi dépasse la limite de taille du nœud ou de la passerelle (413). Envoyez par lots ou placez les fichiers sur le serveur et importez le répertoire.",
  "入口暂时无法连接中央服务（502）。请检查中央进程和隧道的 origin 地址。": "La passerelle ne peut pas joindre le service central (502). Vérifiez le processus central et l'URL d'origine du tunnel.",
