  "删除中央文件归档及其派生内容和依赖记忆，并清除已有洞察；来源设备上的原文件保留。": "Supprime cette archive de fichiers centrale, le contenu dérivé et les mémoires dépendantes, et efface les insights existants. Les fichiers d'origine sur les appareils sources sont conservés.",
  "删除这条原始记录及不再被引用的影像，并清除依赖记忆和已有洞察。": "Supprime cet enregistrement original ainsi que les images non référencées, les mémoires dépendantes et les insights existants.",
  "导入仍保留原始文件与解析资料；如需一并删除，请到导入页删除整次导入。": "L'importation conserve les fichiers originaux et le matériel analysé. Supprimez l'importation entière sur la page Importations pour les retirer aussi.",
  "图片去重 · 仅元数据": "Déduplication d'images · Métadonnées uniquement",
  "画面命中所选去重档位，只保留时间、应用和采样元数据，未保存图片或 OCR 文本。": "Correspond au niveau de déduplication sélectionné. Seules les métadonnées d'heure, d'application et d'échantillonnage ont été conservées ; aucune image ni texte OCR n'a été enregistré.",
  "OCR 待充电": "OCR en attente d'alimentation",
  "截图已保存，采集端接入电源后会自动补做文字识别，再同步识别结果。": "Capture d'écran enregistrée. Le collecteur reconnaîtra le texte une fois branché, puis synchronisera le résultat.",
  "OCR 待处理": "OCR en attente",
  "截图已保存，正在等待采集端处理并同步文字识别结果。": "Capture d'écran enregistrée, en attente de la reconnaissance et de la synchronisation du résultat par le collecteur.",
  "OCR 已完成": "OCR terminée",
  "采集端已完成文字识别，下方显示这条记录保留的全文。": "La reconnaissance de texte est terminée sur le collecteur. Le texte complet conservé apparaît ci-dessous.",
