  "媒体采集已关闭": "Collecte multimédia désactivée",
  "当时没有启用媒体采集，无法判断是否有音频播放。": "La collecte multimédia était désactivée ; la lecture audio à ce moment est inconnue.",
  "媒体采集等待授权": "Collecte multimédia en attente d'autorisation",
  "请在 Android 客户端开启媒体采集，并在系统设置授权通知使用权，以读取应用公开的媒体会话。": "Activez la collecte multimédia sur le client Android et accordez l'accès aux notifications dans les paramètres système pour lire les sessions multimédias publiques.",
  "媒体状态不可用": "État du média indisponible",
  "系统当时未能提供媒体状态，不能据此认定没有音频播放。": "Le système n'a pas pu fournir l'état du média ; cela ne confirme pas l'absence de lecture audio.",
  "未观察到媒体会话": "Aucune session multimédia observée",
  "这次观察没有发现可见的媒体会话；未公开媒体会话的应用可能无法被记录。": "Aucune session multimédia visible lors de cette observation. Les applications ne publiant pas de sessions multimédias peuvent ne pas être enregistrées.",
  " · {0} 个会话": " · {0} sessions",
  "正在播放{0}": "Lecture en cours{0}",
  "{0} 个媒体会话": "Sessions multimédias : {0}",
  "应用通过系统公开的媒体状态；播放状态不代表你实际收听或专注。": "L'état du média publié par l'application ne confirme ni l'écoute réelle ni l'attention.",
  "应用通过系统公开的媒体状态，不包含音频录制或语音转写。播放时长只累计已观察到的播放区间；暂停、未授权和采样空隙不会补齐，也不能据此确定你实际收听。": "L'état du média publié par l'application exclut l'enregistrement audio et la transcription. La durée ne compte que les intervalles de lecture observés ; les pauses, les autorisations manquantes et les lacunes d'échantillonnage ne sont pas comblées. Cela ne prouve pas une écoute réelle.",
  "{0}须为有效的 JSON 对象。": "{0} doit être un objet JSON valide.",
  "{0}须为 JSON 对象，不能是数组或空值。": "{0} doit être un objet JSON, pas un tableau ni une valeur nulle.",
  "模型服务地址须为完整的 HTTP(S) 地址。": "L'URL du service de modèle doit être une URL HTTP(S) complète.",
  "模型服务地址不能含凭据、查询参数或片段。": "L'URL du modèle ne peut pas contenir d'identifiants, de paramètres de requête ni de fragments.",
  "远程模型服务须使用 HTTPS；本机回环地址可使用 HTTP。": "Les modèles distants requièrent HTTPS ; les services en boucle locale peuvent utiliser HTTP.",
  "免密访问仅适用于本机回环地址。": "L'accès non authentifié est limité aux adresses de boucle locale.",
  "输出 token 上限须为 1–128000 之间的整数。": "La limite de tokens de sortie doit être un entier entre 1 et 128 000.",
  "最长等待时间须为 5–600 秒。": "Le délai d'attente doit être de 5 à 600 secondes.",
  "Codex Server 不暴露内部单次模型生成请求，此项不适用。": "Codex Server n'expose pas de requête de génération de modèle unique interne ; ce paramètre ne s'applique pas.",
  "服务或地址已改变。请填写新凭据、清除旧凭据，或明确允许在新地址复用。": "Le service ou l'URL a changé. Remplacez ou effacez les identifiants, ou autorisez explicitement leur réutilisation.",
  "请填写新 API key，或选择清除已有密钥。": "Saisissez une nouvelle clé API ou choisissez d'effacer la clé enregistrée.",
