  "本机随手记待同步空间已满，请先同步或导出待传内容。": "La file d'attente des notes locales est pleine. Synchronisez ou exportez d'abord les notes en attente.",
  "中央节点确认的随手记 ID 不匹配；本机记录已保留。": "L'accusé de réception central indique un ID de note différent. L'enregistrement local est conservé.",
