  "自定义模型地址必须为 HTTPS 且不能含账号、查询参数或锚点": "L'URL du modèle personnalisé doit utiliser HTTPS, sans identifiants, requêtes ni fragments",
  "选择自定义来源后，请填写模型目录 URL": "Saisissez une URL de répertoire de modèle pour la source personnalisée",
  "令牌格式不正确": "Format de jeton invalide",
  "同步方式无效": "Mode de synchronisation invalide",
  "同步间隔（分钟）": "Intervalle de synchronisation (minutes)",
  "批量同步条数": "Taille de lot de synchronisation",
  "采样间隔（毫秒）": "Intervalle d'échantillonnage (millisecondes)",
  "本地队列容量": "Capacité de la file locale",
  "本地队列事件数": "Nombre d'événements de la file locale",
  "空闲暂停秒数": "Secondes de pause d'inactivité",
  "诊断采样秒数": "Secondes d'échantillonnage des diagnostics",
  "JPEG 质量": "Qualité JPEG",
  "截图最大边长": "Bord maximal des captures d'écran",
  "低电量暂停百分比": "Pourcentage de pause en cas de batterie faible",
  "最大生成 token 数": "Nombre maximal de tokens générés",
  "审查图片最大边长": "Bord maximal de l'image de révision",
  "本地推理线程数": "Threads d'inférence locale",
  "本地推理超时（毫秒）": "Délai d'inférence locale (millisecondes)",
  "还有待上传记录，不能切换节点或令牌；请先完成上传或备份处理旧队列": "Des enregistrements en attente empêchent de changer de nœud ou de jeton. Envoyez-les, ou sauvegardez et traitez d'abord l'ancienne file.",
  "还有待上传记录，不能切换中央节点；请先完成上传，或导出并移走旧队列后重启": "Des enregistrements en attente empêchent de changer de nœud. Envoyez-les, ou exportez et déplacez l'ancienne file avant de redémarrer.",
  "切换中央节点必须明确输入新节点令牌，不能复用已有令牌": "Changer de nœud exige la saisie explicite d'un nouveau jeton ; les jetons existants ne peuvent pas être réutilisés",
  "远程部署至少需要 32 字符访问令牌": "Le déploiement distant exige un jeton d'accès d'au moins 32 caractères",
  "设备标识无效": "ID d'appareil invalide",
  "系统密钥存储不可用，无法解密令牌": "Stockage de clés système indisponible ; impossible de déchiffrer le jeton",
  "无法读取配置：请检查系统密钥存储或备份后修复配置文件": "Impossible de lire la configuration. Vérifiez le stockage de clés système, ou sauvegardez puis réparez le fichier de configuration.",
  "系统加密存储不可用，拒绝保存明文令牌": "Stockage chiffré système indisponible ; refus d'enregistrer le jeton en clair",
  "本地记录的节点绑定信息无效": "Liaison de nœud invalide pour les enregistrements locaux",
  "本地待上传记录已绑定原节点或凭据，不能重新归属；请恢复原连接完成同步": "Les enregistrements en attente sont liés à leur nœud ou identifiant d'origine. Restaurez cette connexion pour synchroniser ; la réattribution est bloquée.",
  "中央确认格式无效，原连接保持不变": "Accusé de réception central invalide ; connexion d'origine inchangée",
  "设备已在中央登记，或邀请已使用；请在中央选择此设备重新生成邀请": "Appareil déjà enregistré ou invitation déjà utilisée. Sélectionnez cet appareil sur le nœud central et générez une autre invitation.",
  "邀请无效、已使用或已过期，请在中央重新生成": "Invitation invalide, déjà utilisée ou expirée. Générez-en une autre sur le nœud central.",
  "中央拒绝此凭据，可能已撤销；原连接未修改": "Le nœud central a rejeté cet identifiant, probablement révoqué. La connexion d'origine est inchangée.",
  "此中央暂不支持连接邀请或连接检查，请升级中央，或使用手动连接": "Ce nœud ne prend pas en charge les invitations ni les vérifications de connexion. Mettez-le à niveau ou connectez-vous manuellement.",
  "连接请求过于频繁，请稍后再试": "Trop de demandes de connexion. Réessayez plus tard.",
  "中央暂时无法连接，请稍后再试": "Nœud central temporairement injoignable. Réessayez plus tard.",
  "连接失败或超时；请检查中央地址、HTTPS 证书和网络，不接受重定向": "Échec ou expiration de la connexion. Vérifiez l'URL du nœud, le certificat HTTPS et le réseau. Les redirections sont rejetées.",
  "请先导入连接邀请，或保存访问令牌": "Importez d'abord une invitation ou enregistrez un jeton d'accès",
  "请导入连接邀请文字": "Importez le texte de l'invitation",
  "请先预览邀请并确认显示的中央地址": "Prévisualisez d'abord l'invitation et confirmez l'URL du nœud affichée",
  "还有待上传截图、随手记或来源版本，不能更换节点或凭据；请先完成上传或备份处理旧队列": "Des captures d'écran, notes rapides ou révisions de sources en attente empêchent de changer de nœud ou d'identifiants. Envoyez-les, ou sauvegardez et traitez d'abord l'ancienne file.",
  "当前采集、上传或来源同步尚未结束，请稍后重试连接": "Une collecte, un envoi ou une synchronisation de sources est encore en cours. Réessayez plus tard.",
  "本地推理进程返回无效结果；本次截图已跳过": "L'inférence locale a renvoyé un résultat invalide ; capture d'écran ignorée",
  "本地模型推理失败；已回收推理进程，下次采样重新加载": "Échec de l'inférence locale. Processus recyclé ; le modèle se recharge au prochain échantillon.",
  "本地推理进程已退出；本次截图已跳过，下次采样自动恢复": "Le processus d'inférence locale s'est arrêté ; capture d'écran ignorée. Il reprendra au prochain échantillon.",
  "本地推理客户端已关闭": "Client d'inférence locale fermé",
  "本地推理正在处理上一张截图；本次已跳过": "L'inférence locale traite la capture d'écran précédente ; celle-ci a été ignorée",
  "本地推理已取消": "Inférence locale annulée",
  "本地推理超时参数无效": "Délai d'inférence locale invalide",
  "无法启动本地推理进程": "Impossible de démarrer le processus d'inférence locale",
  "无法启动本地推理进程；本次截图已跳过": "Impossible de démarrer le processus d'inférence locale ; capture d'écran ignorée",
  "本地推理超时；已终止独立进程，本次截图已跳过": "Délai d'inférence locale dépassé ; processus isolé terminé et capture d'écran ignorée",
  "本地推理已取消；本次截图已跳过": "Inférence locale annulée ; capture d'écran ignorée",
