  "尚未运行批量解密": "Le déchiffrement en lot n'a pas encore été exécuté",
  "正在读取本机文件目录…": "Lecture de la liste des fichiers locaux…",
  "正在逐个解密本机内容": "Déchiffrement du contenu local fichier par fichier",
  "已取消，未处理文件保持原样": "Annulé ; les fichiers non traités restent inchangés",
  "处理结束": "Traitement terminé",
  "{0}：解密 {1}，跳过 {2}，失败 {3}；失败文件保留": "{0} : {1} déchiffrés, {2} ignorés, {3} échecs ; les fichiers en échec sont conservés",
  "legacy（日常原目录）": "legacy (répertoire quotidien d'origine)",
  "连接尚未检查": "Connexion non vérifiée",
  "此连接仅有采集权限。请在设置的“连接与设备”中展开“设备身份与管理员访问”，使用单独管理员令牌打开中央仓库": "Cette connexion n'a que l'accès collecte. Dans Paramètres → Connexion et appareils → Identité de l'appareil et accès propriétaire, utilisez un jeton propriétaire distinct pour ouvrir l'archive centrale.",
  "完整中央仓库需要管理员权限；采集专用凭据不能用于此登录": "L'archive complète exige l'accès propriétaire. Les identifiants de collecteur ne peuvent pas se connecter ici.",
