  "正在结束当前采集": "Finalisation de la capture en cours",
  "正在保存随手记": "Enregistrement de la note rapide",
  "系统未允许修改登录启动项，请在系统设置检查": "Le système a refusé la modification de l'élément de connexion. Vérifiez les réglages système.",
  "设置提交需要恢复；已停止采集与上传并保留数据，请重新打开 Mote。": "La validation des paramètres nécessite une récupération. Collecte et envois arrêtés ; données conservées. Rouvrez Mote.",
  "登录项还原失败": "Échec de la restauration de l'élément de connexion",
  "设置未完成；原持久配置和截图保留，运行状态无法安全还原。请重新打开 Mote 后重试": "Paramètres incomplets. La configuration persistante et les captures d'écran sont conservées, mais l'état d'exécution n'a pas pu être restauré en toute sécurité. Rouvrez Mote et réessayez.",
  "已安全保存采集凭据；可测试连接。完整仓库需单独管理员登录。": "Identifiant de collecteur enregistré en toute sécurité. Testez la connexion ; l'archive complète exige une connexion propriétaire distincte.",
  "连接已保存，可测试权限与节点版本": "Connexion enregistrée. Testez les autorisations et la version du nœud.",
  "连接邀请文件超过大小限制": "Le fichier d'invitation dépasse la limite de taille",
  "邀请导入方式无效": "Méthode d'importation d'invitation invalide",
  "二维码图片导入暂仅支持 macOS，请使用 JSON 或连接链接": "L'importation d'image QR exige actuellement macOS. Utilisez JSON ou un lien de connexion.",
  "选择中央连接二维码图片": "Sélectionner une image QR de connexion au nœud central",
  "选择中央连接邀请 JSON": "Sélectionner un fichier JSON d'invitation de connexion centrale",
  "无法读取有效邀请，请检查 JSON/二维码格式、有效期和文件大小；原连接未变动": "Impossible de lire une invitation valide. Vérifiez le format JSON/QR, la date d'expiration et la taille du fichier. La connexion d'origine est inchangée.",
  "系统加密存储不可用，不能交换并保存凭据": "Stockage chiffré système indisponible ; impossible d'échanger et d'enregistrer les identifiants",
  "中央凭据身份确认不一致，原连接未修改；请重新生成邀请": "Incohérence d'identité de l'identifiant central. Connexion d'origine inchangée ; générez une autre invitation.",
  "采集连接成功；可上传记录与同步自身来源，完整仓库需单独管理员登录": "Collecteur connecté ; les enregistrements et les sources propres peuvent se synchroniser. L'archive complète exige une connexion propriétaire distincte.",
  "正在验证已保存连接与权限…": "Vérification de la connexion enregistrée et des autorisations…",
  "采集连接正常 · 仅上传与自身来源同步": "Connexion collecteur valide · Envois et sources propres uniquement",
  "管理员连接正常 · 可访问完整中央仓库": "Connexion propriétaire valide · Accès complet à l'archive centrale",
  "连接检查失败；已保存配置未改变": "Échec de la vérification de connexion ; configuration enregistrée inchangée",
  "管理员令牌格式不正确": "Format de jeton propriétaire invalide",
  "连接已改变，请刷新采集记录": "La connexion a changé. Actualisez les captures.",
  "自定义环境": "Environnement personnalisé",
