  "选择持续同步到中央仓库的本地资料": "Sélectionnez les documents locaux à synchroniser en continu vers l'archive",
  "UTF-8 文本资料": "Documents texte UTF-8",
  "导出本机数值诊断（不含内容与令牌）": "Exporter les diagnostics numériques locaux (sans contenu ni jetons)",
  "导出支持包（数值与固定事件，不含内容和令牌）": "Exporter le pack d'assistance (métriques et événements fixes ; sans contenu ni jetons)",
  "本机内容解密正在进行": "Déchiffrement du contenu local en cours",
  "正在准备解密；采集与同步会暂时暂停": "Préparation du déchiffrement ; la collecte et la synchronisation vont brièvement s'interrompre",
  "解密未完成，原文件保留": "Déchiffrement incomplet ; les originaux sont conservés",
  "选择本机截图保存位置": "Sélectionner l'emplacement local des captures d'écran",
  "选择位置": "Choisir l'emplacement",
  "无法打开截图目录，请检查磁盘是否已连接": "Impossible d'ouvrir le répertoire des captures d'écran. Vérifiez que le disque est connecté.",
  "命名环境请使用带 --profile 的启动命令；系统默认登录项不能保留环境参数": "Pour les environnements nommés, lancez avec --profile. Les éléments de connexion système par défaut ne peuvent pas conserver les arguments d'environnement.",
  "请通过本机文件夹选择器选择截图位置，再保存设置": "Choisissez l'emplacement des captures d'écran avec le sélecteur de dossier local, puis enregistrez",
  "请先保存截图位置，再单独保存节点连接；每次切换均会自动应用": "Enregistrez d'abord l'emplacement des captures d'écran, puis la connexion au nœud séparément. Chaque changement s'applique automatiquement.",
  "请先停止采集，再修改本地模型": "Arrêtez la collecte avant de modifier le modèle local",
  "导入千问语言模型和视觉投影 GGUF（校验 SHA-256）": "Importer les fichiers GGUF du modèle de langage Qwen et de la projection visuelle (vérifiés par SHA-256)",
  "导出已脱敏待上传队列（包含个人资料）": "Exporter la file d'attente d'envoi caviardée (contient des données personnelles)",
  "导入 Mote 电脑端队列备份": "Importer une sauvegarde de file Mote de bureau",
  "Mote 存储或配置需要恢复": "Le stockage ou la configuration de Mote nécessite une récupération",
  "未开启采集，现有数据已保留": "Collecte non démarrée ; les données existantes sont conservées",
  "无法读取配置或持久队列": "Impossible de lire la configuration ou la file persistante",
  "{0}\n如使用外接磁盘，请连接原磁盘后重试。应用不会创建空队列替代原目录。": "{0}\nSi vous utilisez un disque externe, connectez le disque d'origine et réessayez. L'application ne remplacera pas le répertoire d'origine par une file vide.",
  "退出": "Quitter",
