  "二维码图片不能超过 8 MiB": "L'image QR ne peut pas dépasser 8 MiB",
  "未找到唯一有效二维码，请选择清晰的单个连接二维码，或导入 JSON": "Aucun code QR unique valide trouvé. Choisissez un code QR d'invitation unique et net, ou importez du JSON.",
  "无法确认前台应用身份，本次记录已跳过": "Impossible d'identifier l'application au premier plan ; enregistrement ignoré",
  "随手记草稿格式无效": "Brouillon de note rapide invalide",
  "正文最多 20000 个字符位，部分表情占多个字符位；原草稿未改动": "La limite de texte est de 20000 unités de code ; certains émoji en utilisent plusieurs. Le brouillon d'origine est inchangé.",
  "心情最多 80 个字符位，部分表情占多个字符位；原草稿未改动": "La limite d'humeur est de 80 unités de code ; certains émoji en utilisent plusieurs. Le brouillon d'origine est inchangé.",
  "随手记草稿无法读取；请先备份草稿文件再修复": "Impossible de lire le brouillon de note. Sauvegardez le fichier de brouillon avant de le réparer.",
  "草稿已更新，请重新载入当前草稿": "Brouillon mis à jour. Rechargez le brouillon actuel.",
  "此草稿已有待完成保存，请先重试保存；不能改写已准备的记录": "Ce brouillon a un enregistrement en attente. Réessayez d'abord l'enregistrement ; les enregistrements préparés ne peuvent pas être modifiés.",
  "草稿已更新，此提交不会重复创建记录": "Brouillon mis à jour ; cet envoi ne créera pas de doublon",
  "请填写随手记正文，不能只有空白": "Saisissez le texte de la note ; les espaces seuls ne sont pas acceptés",
  "心情不能只有空白；清空心情后也可以保存": "L'humeur ne peut pas contenir uniquement des espaces. Effacez-la pour enregistrer sans humeur.",
  "提交版本已过期，请重新保存当前草稿": "La révision d'envoi a expiré. Enregistrez à nouveau le brouillon actuel.",
  "待完成记录属于原中央节点，请恢复原节点完成保存": "L'enregistrement en attente appartient au nœud d'origine. Restaurez-le pour terminer l'enregistrement.",
  "待完成记录不能改写，请重新载入草稿后重试": "L'enregistrement en attente ne peut pas être modifié. Rechargez le brouillon et réessayez.",
  "本地模型客户端已关闭": "Client de modèle local fermé",
  "本地千问视觉模型正在下载或校验，请完成后再开始采集": "Le modèle visuel Qwen local est en cours de téléchargement ou de vérification. Terminez avant de démarrer la collecte.",
  "本地千问视觉模型缺失或校验失败；请先下载、续传或导入模型": "Modèle visuel Qwen local manquant ou invalide. Téléchargez-le, reprenez le téléchargement ou importez-le d'abord.",
  "本地视觉推理已取消": "Inférence visuelle locale annulée",
  "无效结果": "Résultat invalide",
