  "模型下载正在进行或客户端已关闭": "Le téléchargement du modèle est en cours ou le client est fermé",
  "下载已取消，断点已保留；点击下载可继续": "Téléchargement annulé ; données partielles conservées. Relancez le téléchargement pour reprendre.",
  "模型下载或校验失败，已保留可续传部分；请重试、更换来源或导入": "Échec du téléchargement ou de la vérification du modèle. Les données reprenables sont conservées. Réessayez, changez de source ou importez.",
  "请先取消模型下载或等待导入完成": "Annulez d'abord le téléchargement du modèle ou attendez la fin de l'importation",
  "导入模型与固定版本大小或 SHA-256 不一致；原模型未被替换": "La taille ou le SHA-256 du modèle importé diffère de la version épinglée. Le modèle d'origine est inchangé.",
  "模型操作进行中，请稍后重载": "Opération sur le modèle en cours. Rechargez plus tard.",
  "本地隐私模型返回值无效；已跳过本次采集": "Le modèle local de confidentialité a renvoyé un résultat invalide ; capture ignorée",
  "本地隐私审查不可用或返回无效结果，已跳过本次采集": "Révision de confidentialité locale indisponible ou invalide ; capture ignorée",
  "请为 --profile 指定环境短名": "Indiquez un nom d'environnement après --profile",
  "只允许指定一个 profile": "Un seul profil peut être spécifié",
  "Profile 需为 1–32 个小写字母、数字、下划线或连字符": "Le profil doit contenir 1 à 32 lettres minuscules, chiffres, traits de soulignement ou traits d'union",
  "开发或测试环境不能自动连接日常节点 47832；请使用独立节点，或在应用设置中明确配置": "Les profils de développement/test ne peuvent pas utiliser automatiquement le nœud quotidien 47832. Utilisez un nœud distinct ou configurez-le explicitement dans l'application.",
  "存储切换的提交状态需要恢复；新旧副本均已保留，请退出并重新打开 Mote": "La validation du changement de stockage nécessite une récupération. Les deux copies sont conservées ; quittez puis rouvrez Mote.",
  "存储目录含符号链接，不能安全迁移；原目录保持有效": "Le stockage contient des liens symboliques et ne peut pas être migré en toute sécurité. Le répertoire d'origine reste actif.",
  "存储目录含特殊文件，不能安全迁移": "Le stockage contient des fichiers spéciaux et ne peut pas être migré en toute sécurité",
  "迁移文件校验失败，原目录保持有效": "Échec de la vérification de la migration ; le répertoire d'origine reste actif",
  "截图目录不能是符号链接或其他文件；请重新选择": "Le répertoire des captures d'écran ne peut pas être un lien symbolique ni un autre fichier. Choisissez à nouveau.",
  "存储目录归属标记无效": "Marqueur de propriété du stockage invalide",
  "截图目录不可用；请连接原磁盘后重试，已有记录不会被空目录替代": "Répertoire des captures d'écran indisponible. Connectez le disque d'origine et réessayez ; les enregistrements ne seront pas remplacés par un répertoire vide.",
  "该存储目录不属于当前环境和设备，不能混用其他环境的队列": "Ce stockage appartient à un autre environnement ou appareil. Les files ne peuvent pas être partagées.",
  "已选择的截图目录不可用；请连接原磁盘后重试。不会新建空队列或自动回退旧副本": "Le répertoire de captures d'écran sélectionné est indisponible. Connectez le disque d'origine et réessayez. Aucune file vide ni copie de secours ne sera créée.",
  "迁移恢复需要的原目录不可用；请连接原磁盘后重试，不会创建空队列": "Le répertoire d'origine nécessaire à la récupération est indisponible. Connectez le disque d'origine ; aucune file vide ne sera créée.",
  "存储目录的节点绑定不完整；已保留迁移副本，请检查原磁盘": "Liaison de nœud du stockage incomplète. Les copies de migration sont conservées ; vérifiez le disque d'origine.",
  "请选择 Mote 应用数据目录以外的文件夹，避免与其他环境或应用文件混用": "Sélectionnez un dossier en dehors des données de l'application Mote pour éviter de mélanger environnements ou fichiers d'application",
  "所选位置已有 Mote 存储目录；请选择其他文件夹，避免覆盖已有记录": "L'emplacement sélectionné contient déjà un stockage Mote. Choisissez un autre dossier pour éviter d'écraser des enregistrements.",
  "新旧存储目录不能相同或互相嵌套": "Les ancien et nouveau répertoires de stockage ne peuvent pas être identiques ni imbriqués",
  "旧副本归属无法确认，已保留待处理": "La propriété de l'ancienne copie ne peut pas être vérifiée ; conservée pour examen",
  "迁移恢复记录无效": "Enregistrement de récupération de migration invalide",
  "迁移记录与当前环境不匹配，请保留目录并检查配置": "L'enregistrement de migration ne correspond pas à cet environnement. Conservez le répertoire et vérifiez la configuration.",
  "上次迁移副本尚未清理，请确认旧磁盘可用后重试": "La copie de migration précédente attend son nettoyage. Assurez-vous que l'ancien disque est disponible, puis réessayez.",
  "目标位置与应用环境目录冲突": "La destination entre en conflit avec le répertoire d'environnement de l'application",
  "新位置已存在文件，迁移不会覆盖或合并已有记录": "La destination contient déjà des fichiers. La migration n'écrasera ni ne fusionnera les enregistrements.",
