  "已保存采集专用凭据；完整仓库需单独管理员登录。": "Identifiant de collecteur enregistré ; l'archive complète exige une connexion propriétaire distincte.",
  "邀请到期：": "Expiration de l'invitation :",
  "同一节点重新授权后，现有待传截图、随手记和来源版本将继续发往此地址。节点身份以此地址和 HTTPS 证书为准；请确认它仍由你控制。": "Après la réautorisation du même nœud, les captures d'écran, notes rapides et révisions de sources en attente continueront vers cette adresse. L'identité du nœud repose sur cette URL et ce certificat HTTPS ; confirmez que vous le contrôlez toujours.",
  "更换节点时，本机必须没有待传截图、随手记或来源版本；设备 ID、隐私设置和本地模型将保留。": "Changer de nœud exige l'absence de captures d'écran, notes rapides ou révisions de sources en attente. L'ID d'appareil, les paramètres de confidentialité et les modèles locaux sont conservés.",
  "请先确认中央地址": "Confirmez d'abord l'URL centrale",
  "正在连接并验证新凭据，此过程无法取消；原配置在确认成功前保持不变。": "Connexion et vérification des identifiants ; cette opération ne peut pas être annulée. La configuration d'origine reste jusqu'au succès.",
  "连接已安全保存；原设备 ID、隐私设置和本地模型保留。": "Connexion enregistrée en toute sécurité. ID d'appareil, paramètres de confidentialité et modèles locaux conservés.",
