  "记录保存后尽快发送。断网或失败时仍留在本机，稍后自动重试。": "Envoyer les enregistrements peu après leur sauvegarde. Hors ligne ou en cas d'échec, ils restent en local pour une nouvelle tentative automatique.",
  "每 {0} 分钟检查并上传待传记录。休眠期间顺延，唤醒后继续。": "Vérifier et envoyer les enregistrements en attente toutes les {0} minutes. Reporté pendant la veille ; reprend au réveil.",
  "攒够 {0} 条，或最早记录等待 {1} 分钟后发送，以先达到的条件为准。每条记录单独确认接收。": "Envoyer à {0} enregistrements ou lorsque le plus ancien attend {1} minutes, selon la première échéance. Chaque enregistrement est confirmé séparément.",
  "不自动上传记录或发送设备状态。点击概览的“立即上传”或来源页的“立即检查并上传”时发送；下次仍由你手动触发。": "Aucun envoi automatique ni rapport d'appareil. Utilisez « Envoyer maintenant » dans Vue d'ensemble ou « Vérifier et envoyer maintenant » dans Sources. Les prochains envois nécessitent aussi une action manuelle.",
  "你填写的节点": "Le nœud que vous avez saisi",
  "本机有 {0} 条尚未绑定节点的待传记录，及可能尚未完成保存的随手记。确认后将归属 {1}，按上传策略发送。": "Cet appareil contient {0} enregistrements en attente non liés à un nœud, et peut-être des enregistrements de notes inachevés. La confirmation les attribue à {1}, puis les envois suivent votre politique.",
