  "所选 {0} 条。{1}保留图不会删除。已同步的中央副本不受影响。恢复后会继续原有同步与 OCR 流程。": "{0} enregistrements sélectionnés. {1}Les images de comparaison conservées ne sont pas supprimées. Les copies centrales synchronisées ne sont pas affectées. Les enregistrements restaurés reprennent leur flux de synchronisation et d'OCR d'origine.",
