  "{0} · 当天 {1} 条 · {2} 个{3} · 第 {4} 页": "{0} · {1} enregistrements ce jour · {2} {3} · Page {4}",
  "同应用连续采样归为一段；切换应用或间隔超过 5 分钟分段。仅按本页日期与现存截图分组，起止范围不代表使用时长。": "Les échantillons continus dans une même app forment une session ; un changement d'app ou un intervalle de plus de 5 minutes en commence une autre. Les groupes utilisent les captures existantes à cette date. Les plages horaires n'indiquent pas la durée d'utilisation.",
  "每 15 分钟按 App 汇集 · 点开查看": "Regroupés par app toutes les 15 minutes · Touchez pour voir",
  "当天没有截图记录。": "Aucune capture d'écran pour ce jour.",
  "系统画面": "Écran système",
  "{0} · {1} 条 · 第 {2} 页": "{0} · {1} enregistrements · Page {2}",
  " · 正在加载缩略图（0/{0}）": " · Chargement des miniatures (0/{0})",
  "当天没有此类记录。请开启相应采集来源并授权，记录按同步策略上传。": "Aucun enregistrement de ce type ce jour. Activez et autorisez la source ; les enregistrements sont envoyés selon la politique de synchronisation.",
