  "无图片": "Aucune image",
  "媒体会话状态": "État de session média",
  "设备状态": "État de l'appareil",
  "中央记录不可更新 · 本机图片已保留": "Enregistrement central non modifiable · Image locale préservée",
  "OCR 更新冲突 · 本机图片和文字已保留": "Conflit de mise à jour OCR · Image et texte locaux préservés",
  "记录内容冲突 · 本机副本已保留": "Conflit de contenu d'enregistrement · Copie locale préservée",
  "已同步 · 本机保留至 {0}": "Synchronisé · Conservé localement jusqu'au {0}",
  "图片已同步 · 本机保留待更新 OCR": "Image synchronisée · Conservée localement en attente de mise à jour OCR",
  "保存在本机 · 待同步": "Enregistré localement · En attente de synchronisation",
  "正在读取详情…": "Chargement des détails…",
  "本机记录已同步并清理，请切换到中央归档查看": "Enregistrement local synchronisé et nettoyé. Consultez-le dans l'archive centrale.",
  "记录已读取，正在加载图片…": "Enregistrement chargé ; chargement de l'image…",
  "原始系统事件 · 不代表已阅读通知或实际执行某项任务。熄屏不等于锁定。": "Événement système brut · ne prouve ni la lecture d'une notification ni l'exécution d'une tâche. Écran éteint ne signifie pas verrouillé.",
  "此记录的已观察播放时长：{0} 秒（不含观测缺口）": "Lecture observée dans cet enregistrement : {0} secondes (hors lacunes d'observation)",
  "媒体观察时间：{0}": "Média observé à : {0}",
  "应用活动 · {0} 毫秒": "Activité de l'app · {0} millisecondes",
  "同步需要处理：{0}": "La synchronisation requiert attention : {0}",
  "采集图片": "Image capturée",
  "图片暂不可用。": "Image temporairement indisponible.",
  "识别文字": "Texte reconnu",
  "此图片未识别到文字。": "Aucun texte reconnu dans cette image.",
  "暂无识别文字。": "Aucun texte reconnu pour l'instant.",
  "记录读取失败，请刷新重试": "Impossible de lire l'enregistrement. Actualisez et réessayez.",
  "中央记录暂不可读取，请检查网络后重试": "Impossible de lire l'enregistrement central. Vérifiez le réseau et réessayez.",
  "本机记录暂不可读取，请刷新重试；文件已保留": "Impossible de lire l'enregistrement local. Actualisez et réessayez ; le fichier est préservé.",
  "采集状态": "État de la collecte",
  "屏幕：{0}": "Écran : {0}",
  "媒体：{0}": "Média : {0}",
  "Mote · 采集状态": "Mote · État de la collecte",
  "你已停止采集，已有记录保留，同步按所选策略运行": "Vous avez arrêté la collecte. Les enregistrements sont préservés ; la synchronisation suit la politique sélectionnée.",
  "同步与恢复": "Synchronisation et récupération",
  "手机负责采集，中央端负责归档。已上传的本机副本按保留时间清理。": "Le téléphone collecte ; le nœud central archive. Les copies locales envoyées sont supprimées après leur durée de conservation.",
  "正在读取本机同步状态…": "Chargement de l'état de synchronisation local…",
  "查看待上传队列": "Voir la file d'attente d'envoi",
  "立即同步待发记录": "Synchroniser les enregistrements en attente maintenant",
  "从未确认的记录继续发送；上传中断只重发未确认记录。同一条记录重试不会生成重复副本。仍遵守 Wi-Fi 设置。": "Reprend l'envoi à partir des enregistrements non confirmés. Les envois interrompus ne renvoient que ces enregistrements, sans créer de doublons. Les paramètres Wi-Fi s'appliquent toujours.",
  "检查两端记录状态": "Vérifier les enregistrements des deux côtés",
  "只检查手机仍保留的采集记录在中央端是否可见；不会把“中央存在”直接当作上传确认，也不会删除或恢复记录。": "Vérifie si les captures encore conservées sur le téléphone sont visibles côté central. La présence centrale n'est pas considérée comme une confirmation d'envoi ; rien n'est supprimé ni restauré.",
  "全量补传 · 本机保留的记录": "Renvoi complet · Enregistrements conservés localement",
  "重新上传本机保留的数据？": "Renvoyer les données conservées localement ?",
  "会重发本机仍保留的截图、OCR 原始事件、通知、设备事件、笔记及已启用来源的保留版本。中央端核验相同 ID 去重，继续补齐缺失数据。\n\n已从手机清理的数据无法补传。中央已删除或内容冲突的记录不会覆盖或恢复，暂停的来源不会启用。此操作可能产生较多流量，仍遵守网络设置。": "Renvoie les captures d'écran, événements OCR bruts, notifications, événements d'appareil, notes et révisions conservées des sources activées. Les vérifications d'ID central dédupliquent et comblent les lacunes.\n\nLes données déjà effacées du téléphone ne peuvent pas être renvoyées. Les enregistrements supprimés ou en conflit côté central ne sont ni écrasés ni restaurés ; les sources en pause restent en pause. Cela peut consommer beaucoup de données ; les paramètres réseau s'appliquent toujours.",
  "开始补传": "Démarrer le renvoi",
  "尚未执行检查或全量补传": "Aucune vérification ni renvoi complet effectué",
  "停止本次检查 / 准备补传": "Arrêter cette vérification / préparation du renvoi",
  "已请求停止检查；已进入待发队列的记录按同步策略保留": "Arrêt demandé. Les enregistrements déjà en file sont conservés selon la politique de synchronisation.",
  "查看记录与冲突": "Voir les enregistrements et conflits",
  "查看来源同步状态": "Voir l'état de synchronisation des sources",
  "需要处理时：\n• 网络或服务暂不可用：自动模式退避重试，手动模式再次点同步。\n• 授权失效：重新连接同一节点后同步。\n• 同 ID 内容冲突 / 中央已删除：保留本机副本，跳过该条继续其他记录，不自动覆盖。\n• 等待 OCR：图片已归档不代表识别完成，识别结果会另行确认。\n\n中央端显示的是上次联系时的状态，不是手机实时状态。": "Quand une action est requise :\n• Réseau/service indisponible : le mode automatique réessaie avec backoff ; le mode manuel nécessite un autre appui.\n• Autorisation expirée : reconnectez le même nœud, puis synchronisez.\n• Conflit d'ID / suppression centrale : conservez la copie locale et continuez les autres enregistrements sans écraser.\n• En attente d'OCR : des images archivées ne prouvent pas que la reconnaissance est terminée ; les résultats sont confirmés séparément.\n\nL'état central reflète le dernier contact, pas l'état en direct du téléphone.",
  "请先配置连接": "Configurez d'abord une connexion",
  "正在读取存储状态": "Lecture de l'état du stockage",
  "{0}\n本机保留 {1} 条 · 待发 {2} 条\n需处理 {3} 条 · 等待 OCR {4} 张\n来源待发 {5} 个版本 / {6} 项设置\n\n{7}\n最后收到上传确认：{8}": "{0}\nConservés localement : {1} · En attente : {2}\nÀ traiter : {3} · En attente d'OCR : {4}\nSources en attente : {5} révisions / {6} paramètres\n\n{7}\nDernière confirmation d'envoi : {8}",
  "请检查存储": "Vérifiez le stockage",
  "本机状态暂不可读：{0}": "État local illisible : {0}",
  "{0} · {1}\n{2} · 点按查看本机副本": "{0} · {1}\n{2} · Appuyez pour voir la copie locale",
  "重新核验此冲突 · 不覆盖中央数据": "Revérifier ce conflit · Ne pas écraser les données centrales",
  "正在调整连接，请稍后重试": "La connexion change. Réessayez dans un instant.",
