  "无法持久保存设置，请检查存储空间": "Impossible de conserver les paramètres. Vérifiez l'espace de stockage libre.",
  "已保存设置发生变化，页面已更新；请检查后重新保存": "Les paramètres enregistrés ont changé ; page mise à jour. Vérifiez puis enregistrez à nouveau.",
  "设置保存与恢复均未持久完成，采集已停止；请检查存储空间并重试": "Ni l'enregistrement ni la restauration n'ont pu conserver les paramètres. Collecte arrêtée ; vérifiez le stockage et réessayez.",
  "连接设置未能持久恢复，采集已停止；原连接恢复资料仍保留": "La récupération de la connexion n'a pas pu être conservée. Collecte arrêtée ; les données de récupération d'origine sont conservées.",
  "待同步资料属于原节点，请先同步到原节点；清空连接不会解除资料绑定": "Les données en attente appartiennent au nœud d'origine. Synchronisez d'abord vers celui-ci ; effacer la connexion ne supprime pas la liaison.",
