  "无法创建目标存储目录": "Impossible de créer le répertoire de destination",
  "无法读取原存储目录": "Impossible de lire le répertoire de stockage d'origine",
  "正在复制并校验文件 {0}/{1}": "Copie et vérification du fichier {0}/{1}",
  "原存储包含无法迁移的条目": "Le stockage d'origine contient des éléments non migrables",
  "复制校验失败，原数据已保留": "Échec de la vérification de copie ; données d'origine conservées",
  "正在验证目标记录与图片": "Vérification des enregistrements et images de destination",
  "存储迁移状态不一致，请保留应用数据": "État de migration incohérent. Conservez les données de l'app.",
  "无法清理旧存储副本": "Impossible de nettoyer l'ancienne copie de stockage",
  "旧目录包含未知子目录，副本已保留": "L'ancien répertoire contient des sous-répertoires inconnus ; copie conservée",
  "旧存储副本清理未完成": "Nettoyage de l'ancien stockage incomplet",
  "当前连接没有查看此记录的权限，请检查连接凭据": "La connexion ne peut pas accéder à cet enregistrement. Vérifiez les identifiants.",
  "此记录已不存在，或中央节点版本尚不支持浏览": "Enregistrement manquant, ou la version du nœud ne permet pas la consultation",
  "中央记录读取失败（HTTP {0}）": "Échec de lecture de l'enregistrement central (HTTP {0})",
