  "记录响应超过大小上限": "La réponse d'enregistrement dépasse la limite de taille",
  "无媒体状态": "Aucun état média",
  "媒体会话": "Session média",
  "媒体采集未启用": "Collecte média non activée",
  "媒体等待授权": "Média en attente d'autorisation",
  "媒体暂不可用": "Média temporairement indisponible",
  "播放中": "Lecture en cours",
  "缓冲中": "Mise en mémoire tampon",
  "连接中": "Connexion en cours",
  "调整进度": "Recherche en cours",
  "切换内容": "Changement de contenu",
  "后台": "Arrière-plan",
  "输出未知": "Sortie inconnue",
  " · 等待充电": " · En attente d'alimentation",
  "OCR 待处理{0}": "OCR en attente{0}",
  "OCR 状态未知（历史记录）": "OCR inconnu (enregistrement historique)",
  "连接或同步策略已变化，本次操作已停止；请重新发起": "La connexion ou la politique de synchronisation a changé. Opération arrêtée ; recommencez.",
  "正在准备全量补传…": "Préparation du renvoi complet…",
  "已安排补传 {0} 条本机采集记录及 {1} 个保留来源版本；实际上传进度见下方同步状态。冲突和中央已删除记录保持隔离。": "{0} captures locales et {1} révisions de sources conservées mises en file pour renvoi. Voir l'état de synchronisation ci-dessous. Les conflits et les enregistrements supprimés centralement restent isolés.",
  "检查完成：中央可见 {0} 条，不可见 {1} 条。检查范围为手机仍保留的采集记录；不可见可能是缺失、删除或无权限，不会自动恢复。来源快照由全量补传时核验。": "Vérification terminée : {0} visibles côté central, {1} non visibles. Porte sur les captures encore conservées sur le téléphone. Non visible peut signifier manquant, supprimé ou non autorisé ; rien n'est restauré automatiquement. Le renvoi complet vérifie les instantanés de sources.",
  "检查失败：连接授权失效，请重新连接同一节点后重试": "Échec de la vérification : autorisation expirée. Reconnectez le même nœud et réessayez.",
  "中央节点尚不支持两端检查，请升级中央端代码；未修改本机状态": "Le nœud ne prend pas en charge les vérifications des deux côtés. Mettez-le à niveau ; état local inchangé.",
  "检查响应未确认": "Réponse de vérification non confirmée",
  "检查响应缺失": "Réponse de vérification manquante",
  "已检查 {0} 条 · 中央可见 {1} · 不可见 {2}": "Vérifiés : {0} · Visibles : {1} · Non visibles : {2}",
  "操作未完成，已完成的步骤保留；请检查网络或存储。本次手动操作可再次点击继续，未删除任何副本。": "Opération incomplète ; étapes terminées conservées. Vérifiez le réseau ou le stockage et appuyez à nouveau pour continuer. Aucune copie n'a été supprimée.",
  "操作已请求；重复点击会合并，等待网络条件或当前操作完成": "Opération demandée. Les appuis répétés sont fusionnés ; en attente des conditions réseau ou de la fin du travail en cours.",
  "图片保存位置": "Emplacement de stockage des images",
  "本机保存待同步、待 OCR 与保留期内的记录和图片。上传后仍可回看，到期才清理。": "Conserve localement les enregistrements et images en attente de synchronisation/OCR pendant la durée de conservation. Les enregistrements envoyés restent consultables jusqu'à leur expiration.",
  "选择内部应用空间，或系统提供的本机／存储卡应用空间。迁移会自动暂停处理、复制并验证已有记录，然后继续原来的采集与同步。草稿、设置及来源缓存保留在内部空间。": "Choisissez le stockage interne de l'app ou l'espace local/carte SD fourni par le système. La migration met en pause le traitement, copie et vérifie les enregistrements, puis reprend la collecte et la synchronisation. Brouillons, paramètres et cache des sources restent en interne.",
  "默认明文保存：记录和索引为 JSON，图片保留原始格式。开发者选项可开启本地内容加密，也可批量解密旧文件。这些是本应用专用目录，不是共享相册；卸载应用会删除本机文件。移除存储卡后会停止使用该位置并提示，不会切到空目录；重新连接后可恢复。": "En clair par défaut : enregistrements et index en JSON, images au format d'origine. Les options développeur permettent d'activer le chiffrement local du contenu ou de déchiffrer par lot les anciens fichiers. Ce sont des répertoires privés de l'app, pas un album partagé ; la désinstallation supprime les fichiers locaux. Retirer une carte arrête l'accès à cet emplacement avec un avis, sans basculer vers un répertoire vide. Rebranchez pour récupérer.",
  "正在读取存储位置…": "Chargement des emplacements de stockage…",
  "当前保存位置\n{0}": "Emplacement actuel\n{0}",
  "位置不可用：{0}\n已保留原位置，请重新连接原介质后重试。": "Emplacement indisponible : {0}\nEmplacement d'origine conservé. Rebranchez le support d'origine et réessayez.",
  "（当前）": "(actuel)",
  "{0}{1}\n可用 {2}\n{3}": "{0}{1}\nDisponible : {2}\n{3}",
  "无法读取系统存储位置：{0}": "Impossible de lire les emplacements système : {0}",
  "刷新存储状态": "Actualiser l'état du stockage",
  "迁移本机保存位置": "Migrer le stockage local",
  "迁移到{0}：\n{1}\n\n已有图片、待 OCR 结果和队列记录会一起迁移。验证成功后切换位置并清理旧副本。中央归档位置保持不变。": "Migrer vers {0} :\n{1}\n\nLes images, résultats OCR en attente et enregistrements en file migrent ensemble. Après vérification, l'emplacement change et l'ancienne copie est nettoyée. L'emplacement de l'archive centrale reste inchangé.",
