  "无障碍截图：{0}\n媒体通知使用权：{1}\n投屏：{2}\n通知：{3}\n使用情况：{4}\n电池优化：{5}\n自启动：系统未提供可靠查询，请在系统设置确认。": "Captures d'accessibilité : {0}\nAccès aux notifications média : {1}\nProjection : {2}\nNotifications : {3}\nAccès à l'usage : {4}\nOptimisation de batterie : {5}\nDémarrage automatique : aucune requête système fiable ; confirmez dans les paramètres système.",
