  "正在检查本机待同步资料…": "Vérification du matériel local en attente de synchronisation…",
  "将本机资料绑定到此节点？": "Lier le matériel local à ce nœud ?",
  "{0}\n\n本机已有尚未绑定的截图、笔记或来源资料。确认后会绑定到这个档案地址，并按你的同步策略发送。请核对这是你自己的节点。": "{0}\n\nCet appareil possède des captures d'écran, notes ou matériaux de sources non liés. La confirmation les lie à cette adresse d'archive et les envoie selon votre politique de synchronisation. Vérifiez qu'il s'agit bien de votre nœud.",
