  "Android 10 内容截图请勾选投屏模式；仅活动无需投屏": "Sur Android 10, les captures exigent le mode projection ; pas l'activité seule",
  "请先启用无障碍截图服务，返回后再开始": "Activez les captures d'accessibilité, puis revenez et démarrez",
  "采集已启用，等待首帧；配置页受系统安全保护": "Collecte activée ; en attente de la première frame. Les pages de paramètres sont protégées par le système.",
  "分级采集需要可靠窗口身份，请先启用无障碍服务；不会读取控件文字": "Les niveaux de collecte exigent une identification fiable des fenêtres. Activez l'accessibilité ; aucun texte d'interface n'est lu.",
  "正在启用采集…": "Activation de la collecte…",
  "节点或配置已变化，请重新点击开始": "Le nœud ou la configuration a changé. Appuyez à nouveau sur Démarrer.",
  "分级采集需要可靠窗口身份，请先启用无障碍服务": "Les niveaux de collecte exigent une identification fiable des fenêtres. Activez l'accessibilité.",
