  "导入失败，请核对模型大小与 SHA-256；原模型保留": "Échec de l'importation. Vérifiez la taille du modèle et le SHA-256 ; le modèle d'origine est conservé.",
  "正在启用投屏采集…": "Activation de la projection d'écran…",
  "节点或采集配置已变化，本次授权已丢弃；请重新点击开始": "Le nœud ou les paramètres de collecte ont changé. Autorisation abandonnée ; appuyez à nouveau sur Démarrer.",
  "你未授予投屏权限，未开始截图": "Autorisation de projection refusée ; captures non démarrées",
