  "暂停采集": "Suspendre la collecte",
  "正在本机采集": "Collecte locale en cours",
  "正在连接本机存储，文件整理将在后台继续…": "Connexion au stockage local ; la maintenance des fichiers continue en arrière-plan…",
  "状态暂不可读取，已有记录保留在本机；稍后自动重试": "État temporairement illisible. Enregistrements conservés localement ; nouvelle tentative automatique.",
  "采集服务未连接：请恢复权限": "Service de collecte déconnecté : restaurez l'autorisation",
  "统计暂不可读取": "Statistiques temporairement illisibles",
  "本周期累计截图记录 {0} · 应用活动 {1} · 媒体 {2} · 笔记 {3} · 已确认 {4}\n拦截 {5} · 失败 {6} · 重试结果 {7}": "Cette période : captures d'écran {0} · Activité {1} · Média {2} · Notes {3} · Confirmés {4}\nBloqués {5} · Échecs {6} · Résultats des nouvelles tentatives {7}",
