  "本周期累计截图记录 {0}    活动 {1}    媒体 {2}    随手记 {3}\n本周期已同步 {4} 条": "Cette période : captures d'écran {0}    Activité {1}    Média {2}    Notes {3}\n{4} enregistrements synchronisés cette période",
  "已连接": "Connecté",
  "未连接": "Déconnecté",
  "{0}\n{1}\n{2}\n{3}\n无障碍 {4} · 使用情况 {5}\n最近采集 {6}": "{0}\n{1}\n{2}\n{3}\nAccessibilité {4} · Accès à l'usage {5}\nDernière capture {6}",
  "尚未连接中央节点，请导入邀请或填写下方设置。": "Aucun nœud central connecté. Importez une invitation ou remplissez les paramètres ci-dessous.",
  "已保存节点：{0}": "Nœud enregistré : {0}",
  "媒体播放状态授权": "Autorisation de lecture média",
  "Android 通过通知使用权开放通知与媒体会话。开启通知采集后，Mote 会保存应用公开的标题、正文、持续状态以及更新和移除事件，并按同步策略上传。设备事件单独记录亮屏、熄屏和锁定状态。各来源需单独开启并点击开始；应用的“不记录”和“仅活动”规则仍适用。系统可能隐藏敏感通知；Mote 不回复通知、不控制播放。": "Android expose les notifications et les sessions média via l'accès aux notifications. Quand la collecte de notifications est activée, Mote enregistre les titres, textes, états persistants, mises à jour et suppressions publics des apps, puis les envoie selon la politique. Les événements d'appareil enregistrent séparément les états d'écran et de verrouillage. Activez chaque source individuellement et appuyez sur Démarrer. Les règles « Exclure » et « Activité seule » s'appliquent toujours. Les notifications sensibles peuvent être masquées ; Mote ne répond jamais ni ne contrôle la lecture.",
  "此系统入口不同，请在应用详情或系统搜索中查找": "Ce système utilise une entrée différente. Cherchez dans Détails de l'app ou la recherche système.",
  "请手动打开系统设置": "Ouvrez les paramètres système manuellement",
  "知道了": "Compris",
  "返回{0}": "Retour à {0}",
