  "\n统计口径与限制\n已保存表示本机入队成功；已上传表示节点已确认收到。待 OCR 的图片在确认上传后仍会保留，补做结果也同步成功后才清理。被过滤的画面不会入队。暂停是原因变更次数，不等于丢弃截图次数；请求可能因系统/进程中断没有后续结果。统计与队列分开持久化，进程在两次写入之间终止时累计数可能少记；当前队列数量包含待识别和同步失败保留的图片。\n": "\nDéfinitions et limites\n« Enregistré » signifie mis en file localement ; « envoyé » signifie confirmé par le nœud. Les images en attente d'OCR restent après l'envoi jusqu'à ce que les résultats OCR soient aussi synchronisés. Les images filtrées ne sont pas mises en file. Les compteurs de pause suivent les changements de raison, pas les captures rejetées. Les demandes interrompues peuvent n'avoir aucun résultat. Statistiques et files persistent séparément, donc une terminaison entre deux écritures peut sous-estimer les totaux. Les compteurs de file incluent les images en attente d'OCR et celles dont la synchronisation a échoué.\n",
  "文件字节合计不是 Android 系统的安装占用；不含 APK、系统配额或其他分区。目录仅可由本应用读取，不是共享相册。": "Les octets de fichiers ne représentent pas l'occupation d'installation Android ; les APK, quotas système et autres partitions sont exclus. Les répertoires sont privés à cette application, pas des albums partagés.",
  "统计或队列暂不可读取，不能按零展示；原始文件保留，请查看支持诊断。": "Statistiques ou file illisibles ; impossible d'afficher zéro. Les originaux sont conservés. Consultez les diagnostics d'assistance.",
  "本机保留记录（第 {0} 页，每页 10 条；图片与文字请打开采集记录）": "Enregistrements conservés localement (page {0}, 10 par page ; ouvrez les enregistrements de capture pour les images et le texte)",
