  "记录 ID：{0}\n创建：{1}\n条目字节：{2}\n本机仍保留此记录；下方历史同一 ID 可关联上传失败和确认。图片与文字可从采集记录查看。": "ID d'enregistrement : {0}\nCréé : {1}\nOctets de l'entrée : {2}\nCet enregistrement reste local. Faites correspondre son ID avec l'historique des échecs et confirmations ci-dessous. Les images et le texte sont dans les enregistrements de capture.",
