  "{0}\n{1}\n记录 ID：{2}\n原因：{3}\n记录字节：{4}\nHTTP：{5}\n耗时：{6}\n不保存内容预览；待上传记录只有匹配节点 ACK 后删除。": "{0}\n{1}\nID d'enregistrement : {2}\nRaison : {3}\nOctets de l'enregistrement : {4}\nHTTP : {5}\nDurée : {6}\nAucun aperçu de contenu n'est enregistré. Les enregistrements en attente ne sont supprimés qu'après un ACK correspondant du nœud.",
