  "中央记录已不可更新；本机保留图片和失败状态，不会重新创建记录": "L'enregistrement central n'est plus modifiable ; l'image locale et l'état d'échec sont conservés. L'enregistrement ne sera pas recréé.",
  "OCR 更新与中央记录冲突；本机图片和文字已保留，请在采集记录中查看": "La mise à jour OCR entre en conflit avec l'enregistrement central. L'image et le texte locaux sont conservés ; consultez les enregistrements de capture.",
