  "采集服务未连接，请打开手机应用恢复权限": "Service de collecte déconnecté. Ouvrez l'application du téléphone pour restaurer l'autorisation.",
  "选择要归档的日历与文件。": "Sélectionnez les calendriers et fichiers à archiver.",
