  "选择录音目录 · 原件归档": "Sélectionner un répertoire audio · Archiver les originaux",
  "立即扫描并同步": "Analyser et synchroniser maintenant",
  "正在调度扫描与同步…": "Planification de l'analyse et de la synchronisation…",
  "来源限制与同步说明": "Limites des sources et synchronisation",
  "来源说明": "À propos des sources",
  "默认扩展名 md/txt/json/csv/ics，正文只接受 UTF-8；单文件 100 KiB、100000 字符，单次最多 200 项和 4 MiB，来源缓存最多 64 MiB（也遵守采集与存储中的队列上限）。超限或扫描不完整会提示，绝不把漏扫项当作删除。\n系统后台任务约每 15 分钟检查一次来源各自的间隔；省电或强行停止可能推迟，重新打开应用可恢复。原件归档每文件最多 512 MiB，Mote 文件暂存最多 1 GiB；自动等待稳定后上传，断网续传。引用模式不读取原件，不受原件大小限制。": "Extensions par défaut : md/txt/json/csv/ics, texte UTF-8 uniquement. Limites : 100 Kio/100000 caractères par fichier ; 200 éléments/4 Mio par analyse ; cache des sources de 64 Mio, également limité par la capacité de la file. Les limites et les analyses incomplètes sont signalées ; les éléments manqués ne sont jamais considérés comme supprimés.\nLes tâches en arrière-plan vérifient les intervalles des sources environ toutes les 15 minutes. L'économie d'énergie ou un arrêt forcé peut les retarder ; la réouverture permet de récupérer. L'archivage des originaux permet 512 Mio par fichier et 1 Gio de stockage temporaire, attend que les fichiers soient stables et reprend les envois hors ligne. Le mode référence ne lit pas l'original et n'a pas de limite de taille d'original.",
  "权限丢失，请重新授权": "Autorisation perdue. Autorisez à nouveau.",
  "中央已暂停；请在中央恢复后重试": "Suspendu au niveau central. Reprenez au niveau central et réessayez.",
  "提供者不可用或缓存已满；保留旧快照，稍后重试": "Fournisseur indisponible ou cache plein. L'ancien instantané est conservé pour réessayer.",
  "等待网络/节点恢复": "En attente du rétablissement du réseau/nœud",
  "节点未确认，原版本保留待发": "Le nœud n'a pas confirmé ; la révision d'origine est conservée en attente d'envoi",
