  "本机已停用": "Désactivé localement",
  "本次扫描未完整：跳过 {0} 项；没有推断这些项已删除。": "Analyse incomplète : {0} éléments ignorés ; ils n'ont pas été considérés comme supprimés.",
  "\n{0}\n{1} · {2} · {3}\n待发 {4} 个版本 · 最近扫描 {5}\n{6}": "\n{0}\n{1} · {2} · {3}\n{4} révisions en attente · Dernière analyse {5}\n{6}",
