  "未授权，不读取日历；可在系统应用权限中重新允许": "Non autorisé ; les calendriers ne sont pas lus. Accordez l'accès dans les autorisations d'application du système.",
  "正在处理上一项操作，请稍后重新选择文件": "L'opération précédente est en cours. Sélectionnez un fichier à nouveau plus tard.",
