  "无法读取文件或持久授权，请重新选择": "Impossible de lire le fichier ou de conserver l'autorisation. Sélectionnez à nouveau.",
  "允许本机扫描并发送这个来源": "Autoriser l'analyse locale et l'envoi de cette source",
  "保存方式（中央已有历史不会随设置更改而删除）": "Mode de stockage (le changement ne supprime pas l'historique central)",
  "原件归档 · 中央保留文件": "Archiver les originaux · Conserver les fichiers au niveau central",
  "仅引用 · 不读取正文": "Référence uniquement · Ne pas lire le texte",
  "文字快照": "Instantané du texte",
  "首次同步范围": "Portée de la synchronisation initiale",
  "已有内容分批导入（默认）": "Importer le contenu existant par lots (par défaut)",
  "首次清点后仅同步新条目": "Après l'inventaire initial, ne synchroniser que les nouvelles entrées",
  "本地删除不影响中央原件；上传后仅清理 Mote 暂存，保留手机原文件。仅同步新增以首次完整清单为基线，重启不会重置。": "La suppression locale n'affecte pas les originaux centraux. Le nettoyage après envoi ne supprime que le stockage temporaire Mote, en préservant les originaux du téléphone. La synchronisation des nouveautés uniquement utilise le premier inventaire complet comme référence ; un redémarrage ne la réinitialise pas.",
  "扫描间隔 / 分钟（15–1440，系统可能推迟）": "Intervalle d'analyse / minutes (15–1440 ; le système peut retarder)",
  "过去多少天（0–365）": "Jours passés (0–365)",
  "未来多少天（1–365）": "Jours futurs (1–365)",
  "允许扩展名，逗号分隔": "Extensions autorisées, séparées par des virgules",
  "排除相对路径：每行一项，* 表示任意字符；区分大小写": "Chemins relatifs exclus : un par ligne ; * correspond à n'importe quels caractères ; sensible à la casse",
  "更改选择、过滤或保留方式会清除这个来源的本机旧待发缓存，按新设置重新扫描；不会自动删除中央历史。停用仅暂停本机检查与同步，中央的启用状态与历史保持不变。移除只影响本机连接。": "Modifier la sélection, les filtres ou le mode de conservation efface l'ancien cache local en attente de cette source et relance l'analyse avec les nouveaux paramètres. L'historique central n'est pas supprimé. La désactivation suspend uniquement les vérifications et la synchronisation locales. La suppression n'affecte que la connexion locale.",
