  "请先检查更新；该发布可能没有匹配当前包名的 Android 资产": "Recherchez d'abord les mises à jour. Cette publication n'a peut-être aucun asset Android correspondant au nom du package.",
  "GitHub 暂时限流，稍后重试": "GitHub a limité le débit des requêtes. Réessayez plus tard.",
