  "文件提供者不可用": "Fournisseur de fichiers indisponible",
  "从上传资料和持续采集中发现安排，逐条核对后添加到你选择的已有日历。备注附加 #Mote 来源标记。": "Découvrez des événements dans les envois et le contexte collecté, vérifiez chacun, puis ajoutez-les à un calendrier existant avec un marqueur de source #Mote.",
  "首次使用：在中央网页「行动」开启发现，并授权此设备查看跨来源的建议及原文片段。": "Première utilisation : activez la découverte et autorisez cet appareil à voir les suggestions multi-sources et les extraits dans les paramètres Actions du nœud central.",
