  "日志读取失败，请重试；原文件保留。": "Impossible de lire les journaux. Réessayez ; le fichier original est conservé.",
  "投屏会话已结束，请点击开始并重新授权；已有记录保留，同步按所选策略运行": "La session de partage d'écran est terminée. Redémarrez et accordez l'autorisation ; les enregistrements existants sont conservés et suivent votre politique de synchronisation.",
