  "请检查所选存储介质，保留应用数据": "Vérifiez le stockage sélectionné et conservez les données de l'application.",
  "本地队列无法读取：{0}": "Impossible de lire la file locale : {0}",
  "扫描中央节点生成的连接二维码\n仅用于本次扫码；画面不保存、不上传。返回可用粘贴或 JSON 文件连接。": "Scannez le QR code de connexion généré par votre nœud central\nLa caméra n'est utilisée que pour le scan ; les images ne sont ni enregistrées ni envoyées. Vous pouvez aussi coller une invitation ou importer un JSON.",
