  "本机文件格式升级失败，原文件已保留": "Échec de la mise à niveau du format local ; le fichier d'origine est conservé",
  "无障碍采集暂不可用，下一周期重试": "La collecte d'accessibilité est indisponible ; nouvelle tentative au prochain cycle",
  "无障碍服务中断，请检查系统设置": "Service d'accessibilité interrompu ; vérifiez les réglages système",
  "通知权限已关闭，为保持采集可见已停止，请授权通知后重新开始": "La collecte s'est arrêtée car l'autorisation de notification est désactivée. Accordez l'autorisation puis redémarrez pour garder la collecte visible.",
  "此系统需投屏模式采集内容；仅应用活动无需截图API": "La capture de contenu nécessite le partage d'écran sur ce système ; l'activité des applications seule ne requiert pas d'API de capture d'écran.",
  "系统未提供截图（代码 {0}），可能是安全窗口或权限变化；未保存内容": "Le système n'a pas fourni de capture (code {0}), probablement à cause d'une fenêtre sécurisée ou d'un changement d'autorisation. Aucun contenu n'a été enregistré.",
  "无障碍服务未连接，等待系统恢复或打开设置重新启用": "Service d'accessibilité déconnecté. Attendez le rétablissement ou réactivez-le dans les réglages.",
  "{0} 条记录需要处理（冲突或中央不可用） · 待发 {1} 条；请打开同步与恢复": "{0} enregistrements nécessitent une action (conflit ou nœud central indisponible) · {1} en attente ; ouvrez Synchronisation et récupération.",
  "{0} 个来源同步需要处理 · 待发 {1} 条；请在来源页面检查权限或连接": "{0} sources nécessitent une action · {1} en attente ; vérifiez les autorisations ou connexions sur la page Sources.",
  "仍有 {0} 条待发及 {1} 项来源设置待确认；暂停或权限不可用的来源需恢复后同步": "{0} enregistrements et {1} paramètres de source nécessitent encore une action ; reprenez les sources en pause ou restaurez les autorisations pour synchroniser.",
  "当前待发已确认 · {0} 张图片等待本机 OCR，完成后继续同步": "Enregistrements en attente confirmés · {0} images attendent l'OCR local et seront synchronisées une fois prêtes.",
  "当前待发记录已获中央确认；这不表示两端保留数量相同": "Le nœud central a confirmé tous les enregistrements en attente ; cela ne signifie pas que les deux côtés conservent le même nombre.",
  "审查 allow 必须是布尔值": "Le champ allow de la révision doit être un booléen",
  "允许响应必须显式包含 rectangles 数组（无敏感区用空数组）": "Une réponse allow doit inclure explicitement un tableau rectangles (vide s'il n'y a pas de zone sensible)",
  "图片去重诊断": "Diagnostics de déduplication d'images",
  "仅保留开启诊断后命中的图片对。图片已完成隐私检查和遮罩，仅在本机保存，不会同步。": "Seules les paires d'images détectées après l'activation des diagnostics sont conservées. Les images ont passé les contrôles de confidentialité et le masquage ; elles restent sur cet appareil et ne sont jamais synchronisées.",
  "最多 20 组、32 MiB，保存期限 24 小时。读取时清理过期记录；系统休眠可能延后后台清理。关闭诊断后清空。": "Jusqu'à 20 paires et 32 Mio, conservées 24 heures. Les enregistrements expirés sont supprimés à la lecture ; la mise en veille peut retarder le nettoyage en arrière-plan. La désactivation des diagnostics les efface.",
  "清空全部诊断图片": "Effacer toutes les images de diagnostic",
  "本机保留 {0} 组去重诊断": "{0} paires de déduplication locales",
  "诊断已关闭，临时图片已清空。可在开发者选项中开启。": "Les diagnostics sont désactivés et les images temporaires ont été effacées. Activez-les dans les options développeur.",
  "暂无图片对。开启后，下一次采集到重复画面时会在这里显示。": "Aucune paire d'images pour l'instant. Une fois les diagnostics activés, la prochaine capture en double apparaîtra ici.",
  "{0} · {1}\n哈希相似度 {2}\n{3}": "{0} · {1}\nSimilarité de hachage {2}\n{3}",
  "诊断读取失败，请重试。采集队列不受影响。": "Impossible de lire les diagnostics. Réessayez ; la file de collecte n'est pas affectée.",
  "正在删除临时图片…": "Suppression des images temporaires…",
  "临时图片删除失败，请重试。": "Impossible de supprimer les images temporaires. Réessayez.",
