  "去重图片对": "Paire d'images en double",
  "删除这组图片": "Supprimer cette paire",
  "档位：{0}\n依据：{1}": "Niveau : {0}\nBase : {1}",
  "哈希相似度 {0}\n计算：1 − {1}/64；这是像素哈希指标，不是模型置信度或语义相似度。": "Similarité de hachage {0}\nCalcul : 1 − {1}/64. Il s'agit d'une mesure de hachage de pixels, pas de la confiance du modèle ni d'une similarité sémantique.",
  "处理后基准图 · 上一次保留的非重复帧\n{0}": "Image de référence traitée · Dernière image non dupliquée conservée\n{0}",
