  "默认配置": "Profil par défaut",
  "模型配置管理": "Profils de modèle",
  "模型配置与分工": "Profils de modèle et attributions",
  "可以保存多个服务商，也可以为同一服务商保存不同模型。每次请求的选择优先于功能默认值。": "Enregistrez plusieurs fournisseurs ou différents modèles d'un même fournisseur. Un choix par requête l'emporte sur les valeurs par défaut des fonctionnalités.",
  "编辑模型配置": "Modifier le profil de modèle",
  "新模型配置": "Nouveau profil de modèle",
  "新增配置": "Ajouter un profil",
  "删除配置": "Supprimer le profil",
  "删除这套模型配置及凭据？已保存的问答保留。": "Supprimer ce profil de modèle et ses identifiants ? Les conversations enregistrées sont conservées.",
  "各功能默认模型": "Modèle par défaut par fonctionnalité",
  "默认模型": "Modèle par défaut",
  " · 未配置": " · Non configuré",
  "保存功能默认值": "Enregistrer les valeurs par défaut",
  "本次模型": "Modèle pour cette requête",
  "功能默认": "Valeur par défaut de la fonctionnalité",
  "配置已不可用，请重新选择": "Profil indisponible ; sélectionnez-en un autre",
  "无法读取模型列表：": "Impossible de charger la liste des modèles : ",
  "模型配置已被删除，请重新选择。": "Ce profil de modèle a été supprimé. Sélectionnez-en un autre.",
  "默认项已恢复部署配置，功能分配保持不变。": "Le profil par défaut a été restauré selon la configuration de déploiement ; les attributions de fonctionnalités restent inchangées.",
  "已保存。选择此配置的新请求将立即使用这些设置。": "Enregistré. Les nouvelles requêtes utilisant ce profil appliqueront ces paramètres immédiatement.",
  "每套配置独立保存服务、模型和凭据；在功能入口或默认分配中选择。": "Chaque profil conserve son propre fournisseur, modèle et identifiants. Choisissez-le à l'entrée d'une fonctionnalité ou dans les attributions par défaut.",
  "配置名称": "Nom du profil",
  "使用中央服务器上 Codex CLI 的文件登录凭据。无需在这里填写 API key。Codex 仍会将选中的上下文发送到其模型服务；最长等待时间生效，输出 token 上限由 Codex 管理。": "Utilise les identifiants de connexion par fichier de Codex CLI sur le serveur central. Aucune clé API n'est requise ici. Codex envoie toujours le contexte sélectionné à son service de modèle. Le délai s'applique ; Codex gère la limite de tokens en sortie.",
  "Codex Server 的单次模型请求由 App Server 内部管理，页面的“单次模型请求超时”不适用于内部模型生成；“Agent 总运行超时”可以留空，留空表示不设置 Mote 的总运行期限。输出 token 上限由 Codex 管理。": "Codex Server gère les requêtes de génération individuelles dans App Server ; le « délai par requête de modèle » de la page ne s'applique pas à la génération interne. Le « délai d'exécution total de l'agent » peut rester vide, ce qui désactive la limite de durée totale de Mote. Codex gère la limite de tokens en sortie.",
  "输出由 Codex 管理": "Sortie gérée par Codex",
  "{0} / {1} 秒": "{0} / {1} secondes",
  "{0}；单次模型请求 {1} 秒；Agent 总运行 {2} 秒": "{0} ; requête de modèle unique {1} secondes ; exécution totale de l'agent {2} secondes",
  "将默认配置恢复为中央节点的启动环境或部署配置，其他配置和功能分配保留。当前未保存的草稿也会清空；不会修改部署文件。": "Restaure le profil par défaut depuis l'environnement de démarrage ou la configuration de déploiement du nœud central. Les autres profils et attributions sont conservés. Les brouillons non enregistrés sont aussi effacés ; les fichiers de déploiement ne sont pas modifiés.",
  "所选模型配置不存在，请重新选择。": "Le profil de modèle sélectionné n'existe pas. Sélectionnez-en un autre.",
  "该配置仍是某项功能的默认模型，请先修改功能默认值。": "Ce profil est encore le modèle par défaut d'une fonctionnalité. Modifiez d'abord la valeur par défaut de la fonctionnalité.",
  "Chat 问答": "Chat",
  "Memory 记忆提取": "Extraction de mémoire",
