  "通过中央服务器上的 Codex App Server 调用已登录账户。推理仍由 Codex 服务完成；需安装 Codex CLI 并在服务器登录。": "Appelle le compte connecté via Codex App Server sur le serveur central. L'inférence passe toujours par le service Codex. Installez d'abord Codex CLI et connectez-vous sur le serveur.",
