  "本地服务必须使用回环地址，远程服务必须使用 HTTPS，地址不可包含凭据或查询参数": "Les services locaux exigent des adresses de bouclage ; les services distants exigent HTTPS. Les URL ne doivent contenir ni identifiants ni paramètres de requête.",
