  "诊断器已关闭": "Les diagnostics sont fermés",
  "诊断配置无效": "Configuration de diagnostics invalide",
  "旧诊断文件不可读，已重新开始数值记录": "L'ancien fichier de diagnostics est illisible ; l'enregistrement numérique a recommencé",
