  "诊断采样或写入失败；采集本身继续按隐私策略执行": "L'échantillonnage ou l'écriture des diagnostics a échoué ; la collecte continue selon votre politique de confidentialité",
  "安装 CLI": "Installer le CLI",
  "配置应用": "Configurer l'application",
  "保存应用": "Enregistrer l'application",
