  "记录通知中心可见内容": "Enregistrer le contenu visible du Centre de notifications",
  "需要 macOS 辅助功能授权。仅记录系统当前公开的通知视图，无法读取未展示或已消失的通知。启用应用排除或仅活动规则时暂停此功能。": "Nécessite l'autorisation d'accessibilité de macOS. Seules les vues de notifications actuellement affichées sont enregistrées ; les notifications masquées ou disparues ne sont pas disponibles. Les règles d'exclusion d'applications ou limitées à l'activité suspendent cette fonctionnalité.",
  "网页版本": "Version web",
  "网页与服务版本不一致，请重新构建网页并刷新页面。": "Les versions web et du serveur diffèrent. Recompilez l'application web et rechargez cette page.",
  "统计中心": "Statistiques",
  "当前磁盘占用，按文件类型和最后修改日期（UTC）汇总。共享文件只计一次；日期分布不是每日新增量。": "Utilisation actuelle du disque par type de fichier et date de dernière modification (UTC). Les fichiers partagés ne sont comptés qu'une fois. La répartition par date ne représente pas la croissance quotidienne.",
