  "导出所选时段内全部已保留日志；日志轮转前已清理的部分无法恢复，导出包会注明覆盖范围。": "Exporter tous les journaux conservés sur la période sélectionnée. Les journaux supprimés ne peuvent pas être récupérés ; l'exportation indique sa couverture.",
