  "允许中央按需读取此目录的正文片段（设备需在线）": "Autoriser la lecture de texte à la demande depuis cette source (l'appareil doit être en ligne)",
  "文件来源每份 ≤16 MiB；支持文本、PDF、Word 和音频。跳过隐藏项和符号链接。": "Fichiers jusqu'à 16 Mio : texte, PDF, Word et audio. Les fichiers cachés et les liens symboliques sont ignorés.",
  "原件归档不能应用文字遮盖，请选择内容索引。": "L'archivage des originaux ne permet pas le masquage du texte. Choisissez l'indexation de contenu pour utiliser le masquage.",
