  "模块使用的模型": "Modèles par module",
  "跟随预设的默认模型，或为模块指定同一连接下的其他模型。单次请求的选择优先。": "Utilisez le modèle par défaut du préréglage ou choisissez un autre modèle sur la même connexion. Les choix par requête sont prioritaires.",
