  "同时复制凭据和高级参数（仅在服务器内部复制）": "Inclure les identifiants et les paramètres avancés (copiés uniquement au sein du serveur)",
  "副本独立保存。修改副本不会影响原预设；更换地址时仍需确认凭据复用。": "La copie est indépendante. Ses modifications n'affectent pas l'original. Changer son point de terminaison nécessite toujours une confirmation pour réutiliser les identifiants.",
  "创建副本": "Créer la copie",
  "删除这套预设及凭据？历史问答保留。": "Supprimer ce préréglage et ses identifiants ? Les conversations passées seront conservées.",
  "部署配置": "Configuration de déploiement",
  "来自本次启动读取的配置文件或环境变量。修改文件后重启生效；需要在页面调整时，请先复制为独立预设。": "Chargée depuis le fichier de configuration ou l'environnement au démarrage. Redémarrez après avoir modifié le fichier. Pour effectuer des modifications ici, copiez-la d'abord en préréglage indépendant.",
  "本机 Codex 登录": "Connexion Codex locale",
  "推理强度 / 最长等待": "Effort de raisonnement / Délai d'attente",
  "正在测试…": "Test en cours…",
  "仅发送固定合成记录，验证模型与只读工具调用。": "Envoie uniquement des enregistrements de test générés pour vérifier le modèle et les appels d'outils en lecture seule.",
  "设置连接与默认模型，其他模块可复用此连接并选择不同模型。": "Configurez une connexion et un modèle par défaut. Les autres modules peuvent réutiliser cette connexion avec des modèles différents.",
  "预设名称": "Nom du préréglage",
  "服务商类型": "Type de fournisseur",
  "使用本机 Codex 的登录账户加载目录，并通过 Codex App Server 调用所选模型。": "Charge le catalogue via le compte Codex local et appelle le modèle sélectionné via Codex App Server.",
  "留空表示此预设尚未就绪。": "Laissez vide pour garder ce préréglage non configuré.",
  "模型 Provider": "Fournisseurs de modèles",
  "连接预设、模型目录、凭据与测试": "Préréglages de connexion, catalogues de modèles, identifiants et tests",
  "模块与模型": "Modules et modèles",
  "为各模块分配预设和模型，设置记忆与回顾": "Attribuer des préréglages et des modèles aux modules ; configurer la mémoire et les revues",
  "旧版默认预设": "Préréglage par défaut hérité",
  "部署配置为只读，请复制为新预设后编辑。": "La configuration de déploiement est en lecture seule. Copiez-la dans un nouveau préréglage avant de la modifier.",
  "中央节点 · 已连接": "Nœud central · Connecté",
  "中央节点 · 正在验证": "Nœud central · Vérification en cours",
  "已连接中央节点，打开连接详情": "Nœud central connecté. Ouvrir les détails de connexion",
  "中央节点连接": "Connexion au nœud central",
  "中央节点连接状态": "État de la connexion au nœud central",
  "未连接中央节点": "Non connecté au nœud central",
  "正在同步中央节点": "Synchronisation avec le nœud central",
  "连接需要处理": "La connexion nécessite une intervention",
  "记录只保存在本机；连接后按你的策略上传。": "Les enregistrements restent sur cet appareil jusqu'à la connexion ; ils sont ensuite envoyés selon vos paramètres de synchronisation.",
  "待同步 {0} 条 · 节点：{1}": "Enregistrements en attente : {0} · Nœud : {1}",
  "{0} 条记录等待中央确认": "{0} enregistrements en attente de confirmation centrale",
  "连接后，采集记录会按同步设置发送": "Après connexion, les enregistrements capturés suivent vos paramètres de synchronisation",
  "连接详情": "Détails de la connexion",
  "查看连接": "Voir la connexion",
  "连接设置": "Paramètres de connexion",
  "正在读取保存的连接与同步状态…": "Lecture de la connexion enregistrée et de l'état de synchronisation…",
  "{0} 条记录等待中央确认 · 节点：{1}": "{0} enregistrements en attente de confirmation centrale · Nœud : {1}",
  "节点已保存，但尚未完成最近一次连接验证：{0}": "Nœud enregistré, mais la dernière vérification de connexion n'est pas terminée : {0}",
  "节点：{0} · 最近一次验证成功": "Nœud : {0} · Dernière vérification réussie",
  "你的个人上下文助手": "Votre assistant personnel de contexte",
  "这次回答没有完成": "Cette réponse n'est pas allée à son terme",
  "再次提问": "Reposer la question",
  "Enter 发送 · Shift+Enter 换行": "Entrée pour envoyer · Maj+Entrée pour un saut de ligne",
  "使用中央服务器上 Codex CLI 的文件登录凭据。无需在这里填写 API key。Codex Server 的单次模型请求由 App Server 内部管理，页面的“单次模型请求超时”不适用于内部模型生成；“Agent 总运行超时”可以留空，留空表示不设置 Mote 的总运行期限。输出 token 上限由 Codex 管理。": "Utilise les identifiants de connexion basés sur des fichiers de Codex CLI sur le serveur central. Aucune clé API n'est nécessaire ici. Codex Server gère les requêtes de modèle individuelles au sein de l'App Server ; le délai d'attente par requête de modèle ne s'applique pas à la génération interne. Le délai d'exécution total de l'Agent peut être laissé vide. Codex gère la limite de jetons en sortie.",
  "HTTP Provider：单次模型 API 请求的期限，包含一次生成和流式响应，不包含后续工具循环。Codex Server 不暴露内部单次模型请求，此项不适用。": "Fournisseur HTTP : le délai pour une requête API de modèle, incluant une génération et sa réponse en flux, mais pas les boucles d'outils ultérieures. Codex Server n'expose pas les requêtes de modèle individuelles ; ce paramètre ne s'applique pas.",
  "从一次 Agent 运行开始到完成，包含多次模型请求、工具调用和结果校验。Codex Server 可留空，留空表示不设置 Mote 的总运行期限。": "Du début d'une exécution d'Agent jusqu'à son achèvement, incluant plusieurs requêtes de modèle, appels d'outils et validation des résultats. Codex Server peut laisser ce champ vide pour désactiver le délai d'exécution total de Mote.",
  "已保存节点 · 待验证": "Nœud enregistré · Vérification en attente",
  "已连接中央节点": "Connecté au nœud central",
  "请输入有效的中央所有者令牌": "Saisissez un jeton de propriétaire central valide",
  "问一问需要中央所有者令牌；设备采集凭据不能读取个人归档。": "Ask nécessite un jeton de propriétaire central ; les identifiants de collecte de l'appareil ne peuvent pas lire votre archive.",
  "请输入问题（最多 8000 字）": "Saisissez une question (8 000 caractères maximum)",
