  "问答请求失败（HTTP {0}），请检查中央节点模型设置或稍后重试。": "La requête Ask a échoué (HTTP {0}). Vérifiez les paramètres du modèle central ou réessayez plus tard.",
  "中央记录冲突或已删除，本机副本保留待处理。": "L'enregistrement central est en conflit ou a été supprimé. La copie locale est conservée pour examen.",
