  "已取消剩余批次，当前批次完成后停止。已保存结果保留。": "Les lots restants ont été annulés ; arrêt après la fin du lot en cours. Les résultats enregistrés sont conservés.",
  "第 {0} 批": "Lot {0}",
  "独立审核": "Révision indépendante",
  "提取记忆": "Extraire les mémoires",
  "准备中": "Préparation",
  "等待模型响应": "En attente de la réponse du modèle",
  "读取证据": "Lecture des preuves",
  "校验结果": "Validation des résultats",
