  " · 最后活动 {0}": " · Dernière activité {0}",
  "较长时间未收到新活动；任务仍在等待，不代表已有新结果。": "Aucune nouvelle activité depuis un moment ; la tâche est toujours en attente, cela ne signifie pas qu'il y a de nouveaux résultats.",
  "继续整理": "Reprendre le traitement",
  "取消剩余批次": "Annuler les lots restants",
  "校验与重试记录": "Historique de validation et des tentatives",
  "审核": "Révision",
  "提取": "Extraction",
  " · 第 {0} 次尝试": " · Tentative {0}",
  " · 候选 {0}": " · Candidat {0}",
  " · 引用 {0}": " · Référence {0}",
  "等待自动重试": "En attente de nouvelle tentative automatique",
  "排队等待执行名额": "En file d'attente pour une capacité d'exécution",
  "正在执行": "En cours d'exécution",
  "失败，等待重试": "Échec, en attente de nouvelle tentative",
  "已保存，立即生效。": "Enregistré et appliqué immédiatement.",
  "执行并发": "Concurrence d'exécution",
  "保存后立即生效，重启后保留。": "Les modifications s'appliquent immédiatement et persistent après le redémarrage.",
  "超出名额的工作会排队。降低上限不会中断正在执行的任务。LLM 名额覆盖一次模型运行及其工具循环；Codex 内部请求不可单独计量。": "Le travail dépassant la capacité est mis en file d'attente. Réduire la limite n'interrompt pas les tâches en cours. La capacité LLM couvre une session de modèle et sa boucle d'outils ; les requêtes internes de Codex ne peuvent pas être mesurées individuellement.",
  "详细过程与运行日志使用相同的 JSON 行格式，包含 prompt、上下文、模型输出和工具过程，可能包含个人内容。关闭后立即停止新增详细记录。": "Les traces détaillées et les journaux d'exécution utilisent le même format JSON Lines et incluent prompts, contexte, sorties du modèle et activité des outils, pouvant contenir des données personnelles. La désactivation arrête immédiatement les nouvelles traces détaillées.",
  "执行队列": "Files d'exécution",
  "Agent：执行中 {0} / {1}，排队 {2}": "Agent : {0} / {1} en cours, {2} en file d'attente",
  "LLM：执行中 {0} / {1}，排队 {2}": "LLM : {0} / {1} en cours, {2} en file d'attente",
  "等待模型执行名额": "En attente de capacité du modèle",
  "模型处理中": "Traitement par le modèle",
  "等待 Agent 执行名额": "En attente de capacité pour l'Agent",
  "Agent 并发": "Concurrence des Agents",
  "运行中的 Agent 上限；可在设置中立即调整。": "Nombre maximal d'Agents en cours d'exécution ; modifiable dans les paramètres avec effet immédiat.",
  "LLM 执行并发": "Concurrence d'exécution LLM",
  "模型运行及工具循环的并发上限。": "Nombre maximal de sessions de modèle simultanées, boucles d'outils incluses.",
  "记忆批次并发": "Concurrence des lots de mémoire",
  "独立证据批次的并发上限。": "Nombre maximal de lots de preuves indépendants simultanés.",
  "先检索 memories 的精选记忆概览，再按需展开相关记忆、observation 和 segments。Memory 未命中不代表原始事件不存在；参考整理覆盖信息，用 changes 的 overview 或全文检索发现尚未整理的增量。只对有意义的发现选择性读取原始证据，核实最终报告的事实、数字、归属和时间。不要穷尽读取本窗口全部原文；预算不足时用已有证据生成范围明确的部分报告，说明未覆盖内容。注意迟到上传、修订、人物归属、偏好变化及计划的未知结果。没有支持时明确说明信息不足。不要声称完整回顾了全部历史。未设置时间过滤，允许跨月检索。": "Recherchez d'abord les aperçus des mémoires sélectionnées dans memories, puis développez à la demande les mémoires, observations et segments pertinents. Une mémoire absente ne signifie pas que l'événement original n'existe pas ; consultez les informations de couverture du traitement et utilisez l'aperçu des changes ou la recherche en texte intégral pour découvrir les ajouts non encore traités. Ne lisez les preuves originales que sélectivement, pour les découvertes significatives, afin de vérifier les faits, chiffres, attributions et dates du rapport final. Ne lisez pas exhaustivement tous les originaux de cette fenêtre ; si le budget est insuffisant, produisez un rapport partiel à la portée explicite en précisant ce qui n'est pas couvert. Tenez compte des envois tardifs, des révisions, des attributions de personnes, des changements de préférences et des résultats inconnus des plans. Indiquez clairement quand les preuves sont insuffisantes. Ne prétendez pas avoir passé en revue tout l'historique. Aucun filtre temporel n'est défini ; les recherches peuvent couvrir plusieurs mois.",
  "Gmail 已连接。请返回 Mote 同步邮件。": "Gmail connecté. Retournez dans Mote pour synchroniser les e-mails.",
  "连接 Gmail（只读）": "Connecter Gmail (lecture seule)",
  "同步邮件正文、发件人和时间，附件仅保留名称与引用。邮件内容作为资料，不自动执行其中的指令。断开后停止读取，已归档邮件保留。": "Synchronise le corps des e-mails, les expéditeurs et les dates ; les pièces jointes ne conservent que nom et référence. Le contenu des e-mails sert de ressource ; leurs instructions ne sont jamais exécutées automatiquement. La déconnexion arrête la lecture et conserve les e-mails déjà archivés.",
  "Gmail 使用现有 Google OAuth 客户端与回调地址。请在 Google Cloud 启用 Gmail API，再到模型与服务配置客户端。": "Gmail utilise le client OAuth Google existant et l'adresse de rappel. Activez l'API Gmail dans Google Cloud, puis configurez le client dans Modèles et services.",
  "历史邮件仍有后续分页": "Des e-mails historiques restent à récupérer",
  " 后续邮件将在下一轮继续同步。": " Les e-mails restants seront synchronisés lors des cycles suivants.",
  "继续同步": "Continuer la synchronisation",
  "尚未启用 MCP。请在系统管理 → 模型与服务 → 来源与外部应用中开启 MCP，并配置独立读令牌后重启；写入还需明确启用并设置允许的信源。": "MCP n'est pas encore activé. Activez MCP dans Administration système → Modèles et services → Sources et applications externes, configurez un jeton de lecture dédié puis redémarrez ; l'écriture nécessite en outre une activation explicite et des sources autorisées.",
  "请先在系统管理 → 模型与服务 → 来源与外部应用中准备 Google OAuth 客户端与回调地址，然后重启节点。": "Préparez d'abord le client OAuth Google et l'adresse de rappel dans Administration système → Modèles et services → Sources et applications externes, puis redémarrez le nœud.",
  "。配置入口在“系统管理 → 模型与服务 → 来源与外部应用”。仅支持 OAuth 的 Chatbot 不能直接使用 Bearer 接入。": ". Configurez ceci dans Administration système → Modèles et services → Sources et applications externes. Les chatbots ne prenant en charge que OAuth ne peuvent pas se connecter directement avec des jetons Bearer.",
  "原件资产目录": "Répertoire des ressources originales",
  "图片、导入文件与目录原件按内容哈希共享分片；观察记录和来源版本各自保留。": "Les images, fichiers importés et originaux de répertoires partagent des fragments adressés par hachage de contenu ; les enregistrements d'observation et les versions de sources conservent leur identité propre.",
  "限制去重原件、记录和处理元数据的逻辑字节；SQLite 索引、WAL、日志等额外占盘。达到上限返回 507，端点保留待传队列。": "Limite les octets logiques des originaux dédupliqués, des enregistrements et des métadonnées de traitement ; les index SQLite, le WAL et les journaux occupent de l'espace disque supplémentaire. Quand la limite est atteinte, le serveur renvoie 507 et les clients conservent leurs files d'envoi en attente.",
  "查看详情": "Voir les détails",
