  "审核记录": "Historique des révisions",
  "复用了相同候选与证据版本的独立审核结果，并重新校验了引用和范围。": "A réutilisé le résultat d'une révision indépendante portant sur les mêmes versions du candidat et des preuves, puis a revérifié les références et la portée.",
  "候选已经过独立模型审核和引用校验；用户确认单独记录。": "Le candidat a fait l'objet d'une révision par un modèle indépendant et d'une vérification des références ; la confirmation de l'utilisateur est enregistrée séparément.",
