  "原安排": "Organisation d'origine",
  "确认后仅在 Mote 中标记完成。": "Après confirmation, l'élément est marqué comme terminé uniquement dans Mote.",
  "确认后更新原建议；尚未写入系统日历。": "Après confirmation, la suggestion d'origine est mise à jour ; elle n'a pas encore été écrite dans le calendrier système.",
  "确认后修改或取消原设备上的这一条日程；不会新建另一条日程。": "Après confirmation, cet événement est modifié ou annulé sur l'appareil d'origine ; aucun nouvel événement n'est créé.",
  "保存后会交给该设备写入，备注中附加 #Mote 标记。不会邀请参与人。": "Après enregistrement, l'événement est transmis à cet appareil pour écriture, avec le repère #Mote dans les notes. Aucun participant ne sera invité.",
  "确认变更": "Confirmer les modifications",
  "资料已归档": "Ressource archivée",
  "OCR、索引和记忆分别处理；处理进度请在任务中心查看。": "L'OCR, l'indexation et la mémoire sont traités séparément ; consultez leur progression dans le centre des tâches.",
