  "所选时段包含未采样时间，结论只覆盖已有记录。": "La période sélectionnée contient du temps non échantillonné ; les conclusions ne couvrent que les enregistrements existants.",
  "部分资料仍未完成处理或仅保留来源引用，内容覆盖不完整。": "Certaines ressources sont encore en cours de traitement ou ne conservent que des références à la source ; la couverture du contenu est incomplète.",
  "此报告是同一范围的新版本，旧报告保留各自的资料快照。": "Ce rapport est une nouvelle version pour la même portée ; les anciens rapports conservent leur propre instantané de ressources.",
  "包括已替代和过期的历史记忆": "Inclure les mémoires remplacées et expirées",
