  "生效于": "Valide à partir du",
  "失效于": "Valide jusqu'au",
  "这是用户主动纠正并确认的版本，原始说明已保留。": "Cette version a été corrigée et confirmée par l'utilisateur ; la description d'origine est conservée.",
  "查看替代版本": "Voir la version de remplacement",
