  "确认后才应用此关系，旧内容仍保留。": "Cette relation n'est appliquée qu'après confirmation ; l'ancien contenu est conservé.",
  "纠正并确认": "Corriger et confirmer",
  "填写你确认的内容。它将作为你的原始说明保存，生成新版本；旧记忆及其证据仍可查看，适用项目保持不变。": "Saisissez le contenu que vous confirmez. Il sera enregistré comme votre description d'origine et générera une nouvelle version ; l'ancienne mémoire et ses preuves restent consultables, et le périmètre de projet applicable reste inchangé.",
