  "已知 {0}": "{0} connu(s)",
  "{0} 次运行未上报底层请求数；累计 token 单独计量。": "{0} exécutions n'ont pas rapporté le nombre de requêtes sous-jacentes ; les jetons cumulés sont mesurés séparément.",
