  "中央处理状态待查询，请在中央任务中心查看": "L'état du traitement central est en attente de vérification ; consultez le centre des tâches central",
  "关联日程已更新或正在执行，请刷新后重新确认": "L'événement associé a été mis à jour ou est en cours d'exécution ; actualisez puis confirmez à nouveau.",
  "同一日程已有等待核实的操作": "Une opération en attente de vérification existe déjà pour cet événement",
