  "文档文字提取": "Extraction de texte de document",
  "所选范围的资料已变化，请生成新的洞察版本。": "Les ressources de la portée sélectionnée ont changé ; veuillez générer une nouvelle version de l'insight.",
  "模型执行超时，请重试。": "L'exécution du modèle a dépassé le délai ; veuillez réessayer.",
  "无法核实原日程": "Impossible de vérifier l'événement d'origine",
  "原日程已不存在，请核实": "L'événement d'origine n'existe plus ; veuillez vérifier.",
  "原日程身份已改变，请核实": "L'identité de l'événement d'origine a changé ; veuillez vérifier.",
  "上次修改结果不明，请核实；不会重复执行": "Le résultat de la dernière modification est inconnu ; veuillez le vérifier, elle ne sera pas exécutée à nouveau.",
  "系统日历已被修改，请重新核实": "Le calendrier système a été modifié ; veuillez vérifier à nouveau.",
  "不修改包含参与人的日程": "Les événements avec des participants ne peuvent pas être modifiés",
  "无法核实日程参与人": "Impossible de vérifier les participants de l'événement",
  "原日程已改变，请核实修改结果": "L'événement d'origine a changé ; vérifiez le résultat de la modification.",
  "请在原设备确认，或使用中央网页": "Veuillez confirmer sur l'appareil d'origine ou utiliser la page web centrale",
  "确认后取消原设备上的这一条日程。": "Après confirmation, cet événement est annulé sur l'appareil d'origine.",
  "确认后取消尚未写入日历的原建议。": "Après confirmation, la suggestion d'origine non encore écrite dans le calendrier est annulée.",
  "正在确认变更…": "Confirmation des modifications…",
  "仅更新原建议": "Mettre à jour uniquement la suggestion d'origine",
  "确认后更新原日程，不新建另一条。": "Après confirmation, l'événement d'origine est mis à jour sans en créer un autre.",
  "确认后仅更新原建议，仍需确认添加到日历。": "Après confirmation, seule la suggestion d'origine est mise à jour ; son ajout au calendrier nécessite encore une confirmation.",
  "模型服务额度不足，恢复账户额度后再继续。": "Le quota du service de modèle est insuffisant ; rétablissez le quota du compte avant de continuer.",
  "模型服务拒绝了本次请求，请调整内容或处理范围。": "Le service de modèle a refusé cette requête ; ajustez le contenu ou la portée du traitement.",
  "自动恢复时间已用完，可手动重试开启新的恢复周期。": "Le délai de récupération automatique est écoulé ; une nouvelle tentative manuelle peut lancer un nouveau cycle de récupération.",
  "相关模型配置已改变，请重试以使用新配置；已完成批次会保留。": "La configuration du modèle concerné a changé ; réessayez pour utiliser la nouvelle configuration. Les lots terminés sont conservés.",
  "后台整理窗口": "Fenêtre de traitement en arrière-plan",
  "行动分析": "Analyse des actions",
  "原始资料已变化，此结果不能发布，请重新处理。": "Les ressources d'origine ont changé ; ce résultat ne peut pas être publié, veuillez relancer le traitement.",
  "处理曾中断，请查看任务中心的恢复状态。": "Le traitement a été interrompu ; consultez son état de reprise dans le centre des tâches.",
  "处理服务离线，请检查服务状态。": "Le service de traitement est hors ligne ; vérifiez son état.",
  "当前连接没有访问权限。": "Cette connexion n'a pas les droits d'accès.",
  "操作未完成。错误码：{0}": "L'opération n'a pas abouti. Code d'erreur : {0}",
  "模型服务地址不正确，请检查配置。": "L'adresse du service de modèle est incorrecte ; vérifiez la configuration.",
  "模型服务暂时不可用，请检查服务配置。": "Le service de modèle est temporairement indisponible ; vérifiez sa configuration.",
  "模型服务暂时限流，请等待任务更新。": "Le service de modèle limite temporairement le débit ; attendez la mise à jour de la tâche.",
  "模型服务未完成请求，请查看任务状态。": "Le service de modèle n'a pas terminé la requête ; consultez l'état de la tâche.",
  "模型服务认证失败，请检查凭据。": "L'authentification auprès du service de modèle a échoué ; vérifiez les identifiants.",
  "模型服务重定向未获允许，请检查地址配置。": "La redirection du service de modèle n'est pas autorisée ; vérifiez la configuration de l'adresse.",
  "模型服务额度不足，请补充额度后继续。": "Le quota du service de modèle est insuffisant ; augmentez-le pour continuer.",
  "模型返回的结果未通过校验。": "Le résultat renvoyé par le modèle n'a pas passé la validation.",
  "模型配置已变化，请在任务中心确认后继续；已完成的步骤会保留。": "La configuration du modèle a changé ; confirmez dans le centre des tâches pour continuer. Les étapes terminées sont conservées.",
  "等待你确认后继续。": "En attente de votre confirmation pour continuer.",
  "自动恢复期限已结束，请在任务中心手动重试。": "Le délai de récupération automatique est écoulé ; réessayez manuellement dans le centre des tâches.",
  "访问凭据已失效，请重新连接。": "Les identifiants d'accès ont expiré ; reconnectez-vous.",
  "请先完成模型配置。": "Veuillez d'abord terminer la configuration du modèle.",
  "请求等待超时，请查看任务状态。": "La requête a dépassé le délai d'attente ; consultez l'état de la tâche.",
  "运行已中断，请查看历史结果后重新发起。": "L'exécution a été interrompue ; consultez les résultats passés avant de la relancer.",
  "连接暂时中断，请检查网络。": "La connexion a été temporairement interrompue ; vérifiez le réseau.",
  "先检索 memories 的精选记忆概览，再按需展开相关记忆、observation 和 segments。Memory 未命中不代表原始事件不存在；参考整理覆盖信息，用 changes 的 overview 或全文检索发现尚未整理的增量。只对有意义的发现选择性读取原始证据，核实最终报告的事实、数字、归属和时间。不要穷尽读取本窗口全部原文；预算不足时用已有证据生成范围明确的部分报告，说明未覆盖内容。注意迟到上传、修订、人物归属、偏好变化及计划的未知结果。没有支持时明确说明信息不足。不要声称完整回顾了全部历史。按照宿主固定范围检索，允许范围内跨月检索。": "Recherchez d'abord les aperçus des mémoires sélectionnées dans memories, puis développez à la demande les mémoires, observations et segments pertinents. Une mémoire absente ne signifie pas que l'événement original n'existe pas ; consultez les informations de couverture du traitement et utilisez l'aperçu des changes ou la recherche en texte intégral pour découvrir les ajouts non encore traités. Ne lisez les preuves originales que sélectivement, pour les découvertes significatives, afin de vérifier les faits, chiffres, attributions et dates du rapport final. Ne lisez pas exhaustivement tous les originaux de cette fenêtre ; si le budget est insuffisant, produisez un rapport partiel à la portée clairement définie à partir des preuves disponibles en précisant ce qui n'est pas couvert. Tenez compte des envois tardifs, des révisions, des attributions de personnes, des changements de préférences et des résultats inconnus des plans. Indiquez clairement quand les preuves sont insuffisantes. Ne prétendez pas avoir passé en revue tout l'historique. Respectez la portée fixée par l'hôte ; les recherches peuvent couvrir plusieurs mois dans cette portée.",
  "日程分析": "Analyse du calendrier",
