  "模型返回的日程建议未通过校验，请重试分析。": "Les suggestions de calendrier renvoyées par le modèle n'ont pas passé la validation ; relancez l'analyse.",
  "上传已暂停；已选择的文件仍保留，可继续上传。": "Envoi suspendu ; les fichiers déjà sélectionnés sont conservés et vous pouvez reprendre l'envoi.",
  "暂停上传": "Suspendre l'envoi",
  "普通文本会自动保存为记录；原件始终保留。": "Le texte brut est enregistré automatiquement comme enregistrement ; les originaux sont toujours conservés.",
