  "这些文件的本机副本仍保留，其他资料会继续同步。": "Les copies locales de ces fichiers sont conservées ; les autres ressources continuent de se synchroniser.",
  "中央已删除此文件": "Ce fichier a été supprimé de l'archive centrale",
