  "模型已安装，等待音频 Worker 启动或安装 Native 运行时": "Modèle installé ; en attente du démarrage du worker audio ou de l'installation du runtime natif",
  "下载并安装本地音频模型": "Télécharger et installer le modèle audio local",
  "新上传录音默认在中央转写并区分匿名说话人；模型未就绪时先归档。单文件时长可在下方设置，不设每日限额。": "Par défaut, les nouveaux enregistrements envoyés sont transcrits au niveau central avec distinction anonyme des locuteurs ; si le modèle n'est pas prêt, ils sont d'abord archivés. La durée maximale par fichier se règle ci-dessous ; il n'y a pas de limite quotidienne.",
  "处理开关与单文件限制": "Traitement et limites par fichier",
  "单个音频最长（分钟）": "Durée audio maximale par fichier (minutes)",
  "等待安装本地模型": "En attente de l'installation du modèle local",
  "超过处理大小或单文件时长限制": "Dépasse la taille de traitement ou la durée maximale par fichier",
  "本地 OCR 模型：": "Modèle OCR local :",
  "OCR Worker 已就绪": "Le worker OCR est prêt",
  "模型已安装，等待 OCR Worker 启动或安装 Native 运行时": "Modèle installé ; en attente du démarrage du worker OCR ou de l'installation du runtime natif",
  "下载并安装 OCR 模型": "Télécharger et installer le modèle OCR",
  "新截图先归档，模型就绪后自动识别；升级前的旧截图不会自动回扫。模型下载不上传截图。": "Les nouvelles captures d'écran sont d'abord archivées, puis traitées automatiquement une fois le modèle prêt. Les captures existantes ne sont pas retraitées après une mise à niveau. Le téléchargement du modèle n'envoie aucune capture.",
  "高级 OCR 服务配置": "Paramètres avancés du service OCR",
  "默认由中央管理本地 Worker；改为远程地址会把已归档截图发送给该服务。": "Par défaut, le nœud central gère le worker local. Utiliser une adresse distante envoie les captures archivées à ce service.",
  "历史未安排": "Image historique non planifiée",
  "历史截图补识别": "OCR rétroactive des captures historiques",
  "升级前的截图不会自动识别。先预览数量，再手动安排；每次最多 100 张。": "Les captures d'écran antérieures à la mise à niveau ne sont pas traitées automatiquement. Prévisualisez le nombre, puis planifiez-les manuellement, par lots de 100 maximum.",
  "预览待补识别截图": "Prévisualiser les captures en attente d'OCR rétroactive",
  "本批 {0} 张{1}": "Ce lot : {0} captures{1}",
  "；还有更多可在本批完成后预览": " ; d'autres peuvent être prévisualisées une fois ce lot terminé",
  "确认安排本批 OCR": "Confirmer la planification de l'OCR pour ce lot",
  "Mote 页面受系统防截屏保护，已跳过；离开后自动恢复": "Les pages Mote sont protégées contre les captures d'écran. La collecte reprend après les avoir quittées.",
  "屏幕采集：{0}": "Collecte d'écran : {0}",
  "与中央资料库共用登录，回答和历史对话自动保存。": "Partage la connexion de votre archive centrale. Les réponses et l'historique des conversations sont enregistrés automatiquement.",
  "截图像素读取失败": "Impossible de lire les pixels de la capture d'écran",
  "本地 OCR 服务正在准备，恢复后将自动继续。": "Le service OCR local se prépare. Le traitement reprendra automatiquement.",
  "模型已安装，正在准备本地 OCR 服务；就绪后会自动处理": "Modèle installé. Le service OCR local se prépare ; le traitement démarrera automatiquement.",
  "目录建议默认": "Valeur par défaut suggérée par le catalogue",
  "当前模型不支持": "Non pris en charge par ce modèle",
  "当前版本暂不支持": "Non pris en charge par cette version",
  "挡位来自所选模型的 Codex 目录。": "Les niveaux d'effort proviennent du catalogue Codex du modèle sélectionné.",
  "当前推理强度不受所选 Codex 模型支持，请重新选择。": "Le modèle Codex sélectionné ne prend pas en charge ce niveau de raisonnement. Choisissez un autre niveau.",
  "未取得 Codex 模型挡位，以下选项尚未核实。": "Les niveaux d'effort du modèle Codex sont indisponibles ; ces options ne sont pas vérifiées.",
  "这里只展示已记录的输入和工具事件；未开启追踪或已过保留期的输入无法还原。": "Seules les entrées et les événements d'outils enregistrés sont affichés. Les entrées ne peuvent pas être restaurées si le traçage était désactivé ou si la rétention a expiré.",
