  "记录已截断，不能还原完整输入。": "Cet enregistrement a été tronqué ; l'entrée complète ne peut pas être restaurée.",
  "此页没有已保留的模型输入或工具事件。": "Aucune entrée de modèle ni événement d'outil conservé sur cette page.",
  "模型可见目录": "Répertoire visible par le modèle",
  "问一问当前可访问的虚拟目录，来自实际只读权限；这不代表某次回答已经读取这些内容。": "Le répertoire virtuel actuellement accessible à Ask, selon ses autorisations réelles en lecture seule. L'accessibilité ne signifie pas qu'une réponse a lu ce contenu.",
  "可访问范围": "Portée accessible",
  "正式资料": "Documents publiés",
  "实际输入与读取轨迹": "Entrées et lectures enregistrées",
  "设备范围": "Portée des appareils",
  "目录按页限量展示；没有列出不代表不存在。原始 Coding 事件包和磁盘路径不会作为模型目录公开。": "Les pages du répertoire sont limitées ; les éléments omis ne sont pas nécessairement absents. Les paquets d'événements Coding bruts et les chemins disque ne sont pas exposés comme répertoires du modèle.",
  "Coding Agent 上传": "Envois du Coding Agent",
  "接收成功表示原件已保留；正文发布、索引和记忆整理分别显示状态。": "Une réception confirme que les originaux sont conservés. La publication, l'indexation et le traitement de la mémoire ont des états distincts.",
  "已接收事件": "Événements reçus",
  "原件大小": "Taille de l'original",
  "已发布资料": "Documents publiés",
  "暂无处理任务": "Aucune tâche de traitement pour le moment",
  "查看聚合正文": "Lire la transcription assemblée",
  "暂无 Coding 来源，请在采集端启用 Coding Agent 同步。": "Aucune source Coding pour le moment. Activez la synchronisation du Coding Agent dans un collecteur.",
  "功能插件": "Modules fonctionnels",
  "以下能力来自当前宿主的实际注册。关闭展示不删除资料，也不改变模型权限。": "Ces capacités proviennent des enregistrements actifs de l'hôte. Désactiver une vue ne supprime pas les documents et ne modifie pas les autorisations du modèle.",
  "正文": "Contenu",
  "来源与处理": "Origine et traitement",
  "覆盖状态": "Couverture",
  "已记录的处理产物": "Artefacts de traitement enregistrés",
  "查看中央端发布的正文、版本、来源和处理产物。": "Parcourir le contenu publié, les révisions, les origines et les artefacts de traitement.",
  "当前范围内暂无已发布资料。": "Aucun document publié dans cette portée.",
  "保存记录（只读）": "Enregistrement sauvegardé (lecture seule)",
  "这是中央端返回的结构化记忆记录；下载文本是导出表示，实际模型输入请查看运行追踪。": "Voici l'enregistrement de mémoire structuré renvoyé par le serveur. Le texte téléchargé est un export ; consultez les traces d'exécution pour les entrées réelles du modèle.",
  "专用视图暂不可用，请查看资料库或重试。": "Cette vue est indisponible. Parcourez la bibliothèque ou réessayez.",
  "已索引资料": "Documents indexés",
  "项目未知（仅关联会话）": "Projet inconnu (session uniquement)",
  "会话项目：{0}": "Projet de session : {0}",
  "优先记住你的经历、感受和选择。代办任务线索放在“事件与资料”，需要时再查原文。": "Priorise vos expériences, vos sentiments et vos choix. Les pistes de tâches déléguées restent dans Événements et sources ; ouvrez les originaux si nécessaire.",
  "已关联项目（名称未知）": "Projet associé (nom inconnu)",
  "这是历史版本，当前资料已更新。": "Ceci est une version historique. Le document actuel a été mis à jour.",
  "查看当前版本": "Voir la version actuelle",
  "来源已更正，正在重新整理资料。完成后可继续查看。": "La source a été corrigée et ce document est en cours de reconstruction. Vous pourrez continuer la lecture une fois prêt.",
  "已确认说话人：{0}": "Intervenant confirmé : {0}",
  "历史证据，仅用于核对当时的内容。": "Preuve historique, conservée pour vérifier ce qui a été enregistré à l'époque.",
  "返回阅读视图": "Retour à la vue de lecture",
  "查看原始结构": "Voir la structure brute",
