  "来源与原文": "Sources et originaux",
  "来源、当前条目与可读取的正文": "Sources, éléments actuels et texte lisible",
  "条目内容": "Contenu des éléments",
  "可访问 · 本次浏览展开": "Accessible · développé dans ce navigateur",
  "当前范围内没有可读取的内容。": "Aucun contenu lisible dans la portée actuelle.",
  "不确定性": "Incertitude",
  "读取原始证据": "Lire les preuves originales",
  "支持证据": "Preuves à l'appui",
  "已展开 {0}–{1} / {2} 个字符": "Caractères développés {0}–{1} sur {2}",
  "已核验的支持原文": "Original à l'appui vérifié",
  "支持原文仅部分展开，请按需继续读取。": "Les originaux à l'appui sont partiellement développés. Poursuivez la lecture si nécessaire.",
  "Agent 目录": "Répertoire de l'agent",
  "这是只读虚拟目录，目录条目按需披露。": "Ceci est un répertoire virtuel en lecture seule. Les entrées sont divulguées à la demande.",
  "从目录开始，逐层展开 Agent 可以读取的内容。": "Commencez par le répertoire et développez ce que l'agent peut lire, couche par couche.",
  "当前范围内暂无条目。没有列出不代表不存在。": "Aucun élément dans cette page et cette portée. Les éléments non listés peuvent exister.",
  "返回来源目录": "Retour aux sources",
