  "一次新对话的首次上下文": "Contexte initial d'une nouvelle conversation",
  "用当前资料预览一次新对话，不调用模型。实际运行以当时记录的输入为准。": "Prévisualisez une nouvelle conversation avec les données actuelles, sans appeler de modèle. Les entrées enregistrées font foi pour une exécution réelle.",
