  "默认包含：系统规则、只读工具说明、当前问题、时间与设备范围，以及最多 5 条记忆线索。": "Inclut par défaut : les règles système, les descriptions des outils en lecture seule, la question, la portée temporelle et des appareils, et jusqu'à 5 pistes de mémoire.",
  "已有对话会按预算带入历史或工作摘要；此处预览的是没有历史的新对话。": "Les conversations existantes incluent un historique budgété ou des résumés de travail. Cette prévisualisation est une nouvelle conversation sans historique.",
  "完整目录、文件正文和原图需要按需读取，原图还受独立授权控制。": "Les répertoires complets, le texte des fichiers et les images originales sont lus à la demande. Les images nécessitent une autorisation distincte.",
