  "在中央节点安装并登录官方 Lark CLI。需要妙记搜索、基础信息、产物读取和媒体导出权限。": "Installez la CLI Lark officielle sur le nœud central et connectez-vous. Les autorisations de recherche Minutes, de métadonnées, d'artefacts et d'export de médias sont requises.",
  "在中央节点安装并登录官方 DWS CLI；所在组织需开启 CLI 接入。钉钉适配器尚未完成真实账号验证。": "Installez la CLI DWS officielle sur le nœud central et connectez-vous. Votre organisation doit activer l'accès CLI. L'adaptateur DingTalk n'a pas été vérifié avec un compte réel.",
  "首次历史导入起点": "Début de l'importation initiale de l'historique",
  "导入终点（留空持续同步）": "Fin de l'importation (laisser vide pour une synchronisation continue)",
