  "已归档转写 {0} 条，音频 {1} 条；等待 {2} 步，需处理 {3} 步。": "{0} transcriptions et {1} fichiers audio archivés ; {2} étapes en attente, {3} nécessitent une intervention.",
  "同步步骤与状态": "Étapes et état de la synchronisation",
  "尝试 {0} 次": "{0} tentatives",
  "录音归档": "Archive des enregistrements",
  "照常使用录音笔。厂商完成上传和转写后，Mote 自动归档并生成可追溯的 Memory。": "Utilisez votre enregistreur comme d'habitude. Une fois que le fournisseur a envoyé et transcrit un enregistrement, Mote l'archive et crée une mémoire traçable.",
  "默认用转写生成洞察，原始音频在后台备份。厂商端删除后，Mote 归档继续保留。停止同步或断开连接会保留历史资料。": "Les transcriptions servent aux insights par défaut ; l'audio original est sauvegardé en arrière-plan. Mote conserve ses archives après une suppression côté fournisseur, l'arrêt de la synchronisation ou la déconnexion du compte.",
  "原始录音": "Enregistrement original",
  "回听原始录音": "Écouter l'enregistrement original",
