  "发送中的内容": "Contenu en cours d'envoi",
  "查看待发条目、阻塞原因与恢复操作": "Voir les éléments en attente, les blocages et les actions de récupération",
  "持续来源": "Sources continues",
  "来源管理": "Gérer les sources",
  "逐个查看范围、暂停或重新授权": "Examiner la portée, suspendre ou restaurer l'accès de chaque source",
  "最近内容": "Contenu récent",
  "查看全部内容": "Voir tout le contenu",
  "尚未添加文件夹。添加后可在这里查看范围和状态。": "Aucun dossier ajouté pour l'instant. Leur portée et leur état apparaîtront ici.",
  "还没有内容。选一个动作，留下第一份资料。": "Aucun contenu pour l'instant. Choisissez une action pour enregistrer votre premier élément.",
  "这里还没有内容。点击添加，选择文件、屏幕或随手记。": "Aucun contenu pour l'instant. Touchez Ajouter pour choisir des fichiers, des écrans ou une note rapide.",
  "保存范围后开始，系统权限按需申请。拒绝授权不影响文件和随手记。": "Enregistrez votre portée pour démarrer. Les autorisations sont demandées selon les besoins ; les refuser n'affecte ni les fichiers ni les notes rapides.",
  "保存范围并开始记录": "Enregistrer la portée et démarrer l'enregistrement",
  "返回首页继续记录": "Revenir à l'accueil pour continuer l'enregistrement",
  "已暂停全部发送 · 本机继续保存": "Tous les envois en pause · L'enregistrement local continue",
  "以后修改，也自动同步": "Synchroniser automatiquement les modifications futures",
  "本机已保存": "Enregistré localement",
  "中央端已收到": "Reçu par l'archive centrale",
