  "暂停这个来源": "Suspendre cette source",
  "持续收集文件夹里的新内容与修改": "Continuer à collecter les fichiers nouveaux et modifiés",
  "保存一次，也可选择以后自动同步": "Importer une fois ou opter pour la synchronisation future",
  "先选择应用范围，再按需授权": "Choisissez les apps, puis accordez les autorisations selon les besoins",
  "离线也能留下想法与片段": "Enregistrez des idées et des extraits hors ligne",
  "正在保存发送状态…": "Enregistrement de l'état d'envoi…",
  "中央问答暂不可用。连接中央后，可以根据已整理的内容提问；文件和随手记仍可在本机保存。": "Les questions centrales sont indisponibles. Connectez-vous pour interroger le contenu traité. Les fichiers et les notes rapides peuvent toujours être enregistrés localement.",
  "查看自动同步的范围，逐个暂停或修复来源。": "Examinez la portée de synchronisation continue. Suspendez ou réparez chaque source.",
  "恢复这个来源": "Reprendre cette source",
