  "未连接中央：先保存本机任务，连接时确认发送范围。": "Archive centrale déconnectée : enregistrez la tâche localement, puis confirmez la portée d'envoi à la connexion.",
  "完整文件的发送目的地：{0}": "Destination du fichier complet : {0}",
