  "来源：{0}": "Source : {0}",
  "中央暂不可用 · 保留本机状态，恢复连接后重试": "Archive centrale indisponible · L'état local est conservé ; réessayez après la reconnexion",
  "登录中央后，可在这里读取原文与整理状态。": "Connectez-vous pour lire ici le contenu original et l'état de traitement.",
