  "从你想留下的内容开始": "Commencez par ce que vous voulez conserver",
  "选择文件、记录屏幕或写下想法。先安全保存在这台 Mac，需要时再找回。": "Choisissez des fichiers, enregistrez votre écran ou notez des idées. Enregistrez-les en sécurité sur ce Mac et retrouvez-les quand vous en avez besoin.",
  "让选定文件夹的变化持续归档": "Continuer à archiver les modifications d'un dossier sélectionné",
