  "选择允许记录的应用与范围": "Choisissez quelles apps et zones peuvent être enregistrées",
  "写下想法，断网也能保存": "Notez des idées et enregistrez-les hors ligne",
  "正在读取本机状态…": "Lecture de l'état local…",
  "查看状态与操作": "Voir l'état et les contrôles",
  "发送到中央 ·": "Envoyer au centre ·",
  "立即发送": "Envoyer maintenant",
  "发送详情 →": "Détails d'envoi →",
  "发送设置 →": "Paramètres d'envoi →",
  "屏幕记录状态 →": "État de l'enregistrement d'écran →",
  "查看全部内容 →": "Voir tout le contenu →",
  "自动来源": "Sources automatiques",
  "管理来源 →": "Gérer les sources →",
  "只读取你明确选择的范围。暂停屏幕记录、暂停来源和暂停全部发送分别生效。": "Seule la portée que vous avez sélectionnée est lue. Suspendre l'enregistrement d'écran, une source ou tous les envois a des effets distincts.",
  "先确认应用与遮挡范围，再由你开始记录。屏幕权限不影响文件和随手记。": "Confirmez les apps et les masques, puis démarrez l'enregistrement vous-même. Les autorisations d'écran n'affectent ni les fichiers ni les notes.",
  "哪些日常可以留下，由你决定。": "Vous décidez de ce qui peut être conservé.",
  "选择应用、遮挡区域和记录方式，开始前会再次确认保存范围。": "Choisissez les apps, les masques et le mode d'enregistrement. Vérifiez la portée enregistrée avant le début de l'enregistrement.",
  "选择记录范围": "Choisir la portée d'enregistrement",
