  "高级记录设置": "Paramètres d'enregistrement avancés",
  "频率、画质与本机存储": "Fréquence, qualité d'image et stockage local",
  "发送详情": "Détails d'envoi",
  "文件、屏幕和想法，在同一处阅读。点开内容即可核对出处和整理状态。": "Lisez fichiers, écrans et idées au même endroit. Ouvrez un élément pour vérifier sa source et son état de traitement.",
  "查看内容": "Voir le contenu",
  "本机与已发送": "Contenu local et envoyé",
  "加载更多": "Charger plus",
  "按日期浏览屏幕与页面记录": "Parcourir les enregistrements d'écran et de pages par date",
  "管理你选择的文件夹、文件、日历和编码对话。每个来源都可单独暂停。": "Gérez les dossiers, fichiers, calendriers et conversations de codage sélectionnés. Suspendez chaque source indépendamment.",
  "确认添加内容": "Confirmer l'ajout de contenu",
  "完整文件会发送到所示中央节点进行处理；提取正文不代表只上传摘要。未连接时先保存本机任务，首次连接须确认发送范围。": "Le fichier complet est envoyé au nœud central affiché pour traitement. Extraire le texte ne signifie pas n'envoyer qu'un résumé. Hors connexion, enregistrez la tâche localement ; confirmez la portée d'envoi à la première connexion.",
  "确认并保存": "Confirmer et enregistrer",
  "日历与编码对话": "Calendriers et conversations de codage",
