  "确认屏幕记录范围": "Confirmer la portée d'enregistrement d'écran",
  "以下是已保存的范围。只有确认后才检查系统权限并开始。": "Voici votre portée enregistrée. L'accès système n'est vérifié et l'enregistrement ne démarre qu'après votre confirmation.",
  "这是生成的格式示意，不读取你的屏幕。仅应用活动不读取屏幕或正文；完整内容保存经过遮挡的截图或获准页面。": "Cet exemple de format généré ne lit pas votre écran. L'activité des apps ne lit ni l'écran ni le texte ; le contenu complet enregistre des captures masquées ou des pages autorisées.",
