  "查看、纠正与整理记忆": "Voir, corriger et organiser la Mémoire",
  "查看「导入与导出」「大资料库适合使用离线备份」以及索引区域。": "Consultez « Importation et exportation », « La sauvegarde hors ligne convient aux grandes bibliothèques » et la section des index.",
  "查看「记录详细 Agent 过程」。": "Consultez « Enregistrer les traces détaillées de l'Agent ».",
  "查看「诊断偏好」，展开「部署与全部生效配置」。": "Consultez « Préférences de diagnostic », puis développez « Déploiement et toute la configuration en vigueur ».",
  "查看按类型与日期的字节、文件数": "Voir les octets et fichiers par type et date",
  "查看保存方式；导出或恢复归档，管理内容加密与检索索引。": "Examinez les politiques de stockage, importez ou exportez des archives, et gérez le chiffrement du contenu et les index de recherche.",
  "查看保留、容量和内容存储政策": "Trouver la politique de conservation, capacité et stockage du contenu",
  "查看保留与容量草稿及实际生效值": "Trouver les valeurs de conservation et capacité configurables et en vigueur",
  "查看本地队列卡片；控制按钮随上传状态出现。": "Consultez les cartes de la file locale ; les contrôles apparaissent selon l'état de l'envoi.",
  "查看并处理导入进度": "Comprendre et contrôler le traitement des importations",
  "查看播放器、标题、状态和播放进度，核对按设备统计的播放观测。": "Consultez le lecteur, le titre, le statut et la progression de lecture, et vérifiez les observations de lecture par appareil.",
  "查看步骤、依赖、尝试和下一可执行步骤": "Examiner les étapes, dépendances, tentatives, prochaine étape exécutable et échec",
  "查看采样得到的各应用时长和占比，理解其统计范围。": "Consultez les durées et parts échantillonnées de chaque application, et comprenez ce que les statistiques couvrent.",
  "查看采样时长": "Examiner la durée échantillonnée",
  "查看测得的应用活动时间": "Examiner l'activité mesurée des applications",
  "查看产品工作，并展开 Coding 会话接收状态。": "Consultez le travail du produit et développez l'état de réception des sessions Coding.",
  "查看产物标识与状态原因": "Examiner les identifiants de sortie et les raisons de statut",
  "查看此厂商的首次授权、历史范围和同步。": "Consultez l'autorisation initiale de ce fournisseur, sa plage historique et sa synchronisation.",
  "查看此来源的会话正文": "Lire les conversations de cette source",
  "查看当前方案；选择替换目标后依次预览、准备、验证和应用。": "Consultez le plan actuel. Choisissez un remplacement, puis prévisualisez, préparez, vérifiez et appliquez dans cet ordre.",
  "查看当前方案和模式": "Examiner le plan et le mode actuels",
