  "查看当前页来源、事件接收数量和字节": "Examiner les sources, les événements reçus et les octets de la page actuelle",
  "查看当前运行的整套记忆实现，准备和验证替换，再单独应用已验证方案。": "Consultez l'implémentation complète de Mémoire en cours d'exécution, préparez et vérifiez un remplacement, puis appliquez le plan vérifié comme étape distincte.",
  "查看当前执行与等待容量": "Voir les capacités actives et en attente",
