  "查看反馈链接；版本也在设置的「版本与更新」或「诊断与更新」。": "Consultez les liens de commentaires. Les versions se trouvent aussi dans Paramètres sous Versions et mises à jour ou Diagnostics et mises à jour.",
  "查看分布及设备汇总": "Voir la répartition et les résumés par appareil",
  "查看服务端与网页实际加载的能力、版本、状态和当前模块绑定。": "Consultez les capacités, versions, statuts et liaisons de modules actuellement chargés par le serveur et l'interface web.",
  "查看该轮附件信息": "Trouver les métadonnées des pièces jointes du tour",
  "查看各功能的实际模型用量、费用记录与估算边界。": "Examinez l'utilisation des modèles, les coûts enregistrés et les limites des estimations pour chaque fonction.",
  "查看各应用占比": "Examiner la part de chaque application",
