  "查看工作进度、分支、结果和需要补充的信息，继续排查技术步骤。": "Consultez la progression du travail, les branches, les résultats et les informations demandées, puis continuez le dépannage des étapes techniques.",
  "查看归档、解析、记录与记忆阶段": "Lire les étapes d'archivage, d'analyse, d'enregistrement et de Mémoire",
