  "查看媒体汇总并展开记录信息。": "Consultez le résumé des médias et développez les informations d'enregistrement.",
  "查看每个连接的名称、权限和状态，撤销不再使用的访问。": "Consultez le nom, les autorisations et le statut de chaque connexion, et révoquez les accès que vous n'utilisez plus.",
  "查看每日趋势": "Examiner la tendance quotidienne",
  "查看模型配置或下载状态": "Trouver l'état du modèle, de la configuration ou du téléchargement",
  "查看某一时间有效的记忆、旧版本和替代或矛盾关系。": "Consultez la Mémoire valide à un moment donné, les anciennes versions et les relations de remplacement ou de contradiction.",
  "查看内容存储政策和数据概览；保留与容量修改位于模型与服务。": "Consultez les politiques de stockage du contenu et l'aperçu des données. Les modifications de conservation et de capacité se trouvent dans Modèles et services.",
  "查看内容关系和上下文": "Voir l'attribution et le contexte",
