  "打开今天、资料库、问一问、活动、采集与设备": "Ouvrir Aujourd'hui, Bibliothèque, Ask, Activité, Collecte et appareils",
  "打开来源与处理页签": "Ouvrir l'onglet source et traitement",
  "打开任务详情": "Trouver le détail de la tâche",
  "打开设置": "Ouvrir les paramètres",
  "打开图片、文字、元数据和附件": "Ouvrir l'image, le texte, les métadonnées et les pièces jointes",
