  "设置提取历史窗口": "Configurer les fenêtres historiques d'extraction",
  "设置提取历史窗口、整合与回顾节奏，以及默认、截图和来源的配方组合。": "Définir la fenêtre rétrospective d'extraction, la cadence d'intégration et de revue, et les combinaisons de recettes par défaut, de capture et de source.",
  "设置向量模型与地址": "Définir le modèle/l'adresse d'embedding",
  "设置页管理语言、当前服务和会话；外部服务及受限 MCP 另行授权。": "Les paramètres gèrent la langue, le service actuel et les sessions. Les services externes et l'accès MCP restreint sont autorisés séparément.",
  "设置与维护": "Paramètres et maintenance",
