  "资料库 → 记忆 → 历史 / 截至时间筛选 → 记忆详情": "Bibliothèque → Mémoire → Filtres d'historique / de date → Détail de la mémoire",
  "资料库 → 记忆 → 提取记忆；原始或正式资料详情 → 记忆提取": "Bibliothèque → Mémoire → Extraire la mémoire ; Détail de l'élément d'origine ou formel → Extraction de mémoire",
