  "资料库 → 全部资料 → 资料详情": "Bibliothèque → Tous les éléments → Détail de l'élément",
  "资料库 → 全部资料 → 资料详情 → 来源与处理 / 记忆入口": "Bibliothèque → Tous les éléments → Détail de l'élément → Origine et traitement / Entrée mémoire",
  "资料库 → 文件与录音": "Bibliothèque → Fichiers et enregistrements",
  "资料库 → 文件与录音 → 文件详情 → 文段 / 说话人试听与命名 / 复核": "Bibliothèque → Fichiers et enregistrements → Détail du fichier → Segments de texte / Écoute et nommage des locuteurs / Révision",
  "资料库 → 文件与录音 → 文件详情；导入 → 媒体详情": "Bibliothèque → Fichiers et enregistrements → Détail du fichier ; Import → Détail du média",
  "资料库 → 应用活动": "Bibliothèque → Activité des applications",
  "资料库 → 原始采集记录": "Bibliothèque → Enregistrements de collecte d'origine",
  "资料库 → 原始采集记录 → 记录 → 完整详情": "Bibliothèque → Enregistrements de collecte d'origine → Enregistrement → Détail complet",
  "资料库 → 原始采集记录 → 完整详情 → 删除这条记录": "Bibliothèque → Enregistrements de collecte d'origine → Détail complet → Supprimer cet enregistrement",
  "资料库分类是内容视图；设备端负责采集，时间统计只基于实际观测。": "Les catégories de la bibliothèque sont des vues de contenu. Les appareils collectent les données ; les statistiques de temps reposent uniquement sur les observations réelles.",
  "资料库分类是已有内容的视图；页面工具与分类视图使用不同入口。": "Les catégories de la bibliothèque sont des vues du contenu existant. Les outils de page et les vues de catégories ont des entrées différentes.",
  "资料库分类是已有内容的视图；Coding 接收状态在处理任务内查看，已发布正文在全部资料阅读。": "Les catégories de la bibliothèque sont des vues du contenu existant. Les réceptions Coding apparaissent dans les tâches de traitement, tandis que le texte publié se lit dans Tous les éléments.",
  "资料库工具 → 导入 → 本地上传队列": "Outils de la bibliothèque → Import → File d'envoi locale",
  "资料库工具 → 导入 → 导入详情": "Outils de la bibliothèque → Import → Détail de l'import",
  "资料库工具 → 导入 → 导入详情 → 删除这次导入": "Outils de la bibliothèque → Import → Détail de l'import → Supprimer cet import",
  "资料库工具 → 导入 → 服务器目录": "Outils de la bibliothèque → Import → Répertoire du serveur",
  "资料库工具 → 导入 → 解析方式 / 修改图片处理": "Outils de la bibliothèque → Import → Méthode d'analyse / Modifier le traitement des images",
  "资料库工具 → 洞察；问一问 → 查看洞察；今天 → 最近洞察": "Outils de la bibliothèque → Insights ; Ask → Voir les insights ; Aujourd'hui → Dernier insight",
  "资料库工具 → 随手记": "Outils de la bibliothèque → Notes rapides",
