  "原任务入口当前不可用，请从主导航继续。": "L'entrée de la tâche d'origine est actuellement indisponible. Continuez depuis la navigation principale.",
  "这里仅核对首个关联执行记录；还有 {0} 个关联记录，可在技术详情继续查看。已有补充问题单独显示在下方。": "Seul le premier enregistrement d'exécution lié est vérifié ici. Il reste {0} enregistrements liés à examiner dans les détails techniques. Les questions de suivi existantes apparaissent séparément ci-dessous.",
  "此资料库分类当前不可用。请从资料库分类中选择可用入口。": "Cette catégorie de la bibliothèque est actuellement indisponible. Choisissez une entrée disponible parmi les catégories de la bibliothèque.",
  "厂商转写格式尚不支持。音频备份是独立步骤，请分别核对转写与音频的状态。": "Le format de transcription du fournisseur n'est pas pris en charge. La sauvegarde audio est une étape distincte ; vérifiez séparément l'état de la transcription et de l'audio.",
  "同步未完成（原因代码：{0}）。请查看同步步骤，核对实际原因后再重试。": "La synchronisation ne s'est pas terminée (code de raison : {0}). Examinez les étapes de synchronisation et vérifiez la cause réelle avant de réessayer.",
  "核对原因后，可使用上方「重试失败步骤」。转写与音频状态分别核对。": "Après avoir vérifié la cause, vous pouvez utiliser « Réessayer les étapes en échec » ci-dessus. Vérifiez séparément l'état de la transcription et de l'audio.",
  "文件夹进度：中央已接收 {0}/{1} 个当前版本（{2}%）": "Progression du dossier : le nœud central a reçu {0}/{1} versions actuelles ({2} %)",
  "等待稳定 {0} · 排队 {1} · 正在保存 {2} · 正在上传 {3} · 失败重试 {4} · 需处理 {5}": "En attente de stabilité {0} · En file {1} · Enregistrement en cours {2} · Envoi en cours {3} · En attente de nouvelle tentative {4} · À traiter {5}",
