  "采集与随手记的上传批次；其他上传结果可在采集与存储详情查看。": "Lots d'envoi des collectes et notes rapides. Les autres résultats d'envoi restent disponibles dans les détails de collecte et de stockage.",
  "上传历史": "Historique des envois",
