  "上传结果详情": "Détails du résultat d'envoi",
  "仅显示本机保留的最近上传结果；中央接收不代表已完成处理。": "Affiche les résultats d'envoi récents conservés sur cet appareil. La réception par le nœud central ne signifie pas que le traitement est terminé.",
  "删除中央保存的这份文件。不会删除设备上的原件，也不会改变来源同步策略。删除后无法恢复。": "Supprimer ce fichier stocké sur le nœud central. Les originaux sur vos appareils et la politique de synchronisation des sources sont inchangés. Cette action est irréversible.",
