  "安装后自动进入连接配置；不会自动核验、启用或更换记忆方案。": "Après l'installation, continuez directement vers la configuration de connexion. La vérification, l'activation et le changement de plan de mémoire restent séparés.",
  "安装未完成，请查看已登记的插件状态。": "L'installation ne s'est pas terminée. Examinez l'état du plugin enregistré.",
  "请检查连接配置；仅使用已有模型与凭据引用，不填写密钥。": "Vérifiez les paramètres de connexion. Utilisez les références de modèle et d'identifiants existantes, pas de valeurs secrètes.",
  "正在核验能力…": "Vérification des capacités…",
  "能力已核验。启用与记忆方案仍需单独选择。": "Capacités vérifiées. L'activation et la sélection d'un plan de mémoire restent des choix séparés.",
  "连接配置已保存，尚未核验能力。": "Paramètres de connexion enregistrés ; les capacités n'ont pas été vérifiées.",
  "核验使用生成测试资料，可能产生模型与 Embedding 费用；Hindsight 会启动 Docker 服务与模型。不会读取或回填个人历史。": "La vérification utilise des données de test générées et peut entraîner des frais de modèle et d'embedding. Hindsight démarre son service Docker et ses modèles. Elle ne lit ni ne recharge l'historique personnel.",
  "已了解核验的连接与费用影响。": "Je comprends les connexions et les frais possibles liés à la vérification.",
  "尚未设为当前记忆方案。": "Non sélectionné comme plan de mémoire actuel.",
  "查看已安装插件": "Voir les plugins installés",
  "离开此引导不会撤销已登记的安装或核验。": "Quitter ce guide n'annule pas une installation ou une vérification déjà enregistrée.",
  "填写连接配置。保存不会运行核验、启用插件或更换记忆方案。": "Saisissez les paramètres de connexion. L'enregistrement ne lance pas la vérification, n'active pas le plugin et ne change pas le plan de mémoire.",
  "正在整理自动主题…": "Organisation des sujets automatiques…",
