  "原始对话或轮次暂不可读，可能已删除、权限已变更或连接中断。已保存的引用未改变。": "La conversation ou le tour d'origine est indisponible. Il peut avoir été supprimé, l'accès peut avoir changé ou la connexion peut être hors ligne. La citation enregistrée est inchangée.",
