  "恢复接入仅允许接收资料；录音同步需在录音同步设置中确认范围并启用。": "Reprendre la réception autorise uniquement cette source à recevoir des éléments. Confirmez la plage et activez la synchronisation des enregistrements dans les paramètres de synchronisation des enregistrements.",
  "录音同步设置": "Paramètres de synchronisation des enregistrements",
  "已保存账号绑定不代表当前登录或读取权限有效。“重新检测”检查中央运行环境；请结合授权结果与同步步骤确认账号权限。": "Une liaison de compte enregistrée ne confirme ni une connexion valide ni des autorisations de lecture. « Revérifier » examine le runtime du nœud central ; confirmez les autorisations du compte à partir des résultats d'autorisation et des étapes de synchronisation.",
  "结构化内容未采集：请先配置允许的 Chrome 站点；应用时长按所选设置记录": "Contenu structuré non collecté : configurez d'abord les sites Chrome autorisés ; la durée d'utilisation suit votre sélection",
  "结构化内容未采集：Mote Chrome 扩展尚未连接；应用时长按所选设置记录": "Contenu structuré non collecté : l'extension Mote Chrome n'est pas connectée ; la durée d'utilisation suit votre sélection",
  "结构化内容未采集：Chrome 窗口、站点授权或遮挡校验未通过；应用时长按所选设置记录": "Contenu structuré non collecté : les vérifications de la fenêtre Chrome, de l'autorisation du site ou de la visibilité ont échoué ; la durée d'utilisation suit votre sélection",
  "切换语言会重新加载页面，请先保存未提交的修改。继续？": "Changer de langue recharge la page. Enregistrez d'abord les modifications en attente. Continuer ?",
  "无法保存语言偏好，请检查浏览器存储。": "Impossible d'enregistrer la préférence de langue. Vérifiez le stockage du navigateur.",
  "切换语言会重新加载界面，请先保存未提交的设置。继续？": "Changer de langue recharge cette fenêtre. Enregistrez d'abord les réglages en attente. Continuer ?",
  "语言保存失败，请重试。": "Échec de l'enregistrement de la langue. Réessayez.",
  "将此应用拖入系统设置的权限列表": "Glissez cette app dans la liste des autorisations des Réglages Système",
  "列表中已有此应用？直接开启它右侧的开关。": "L'app figure déjà dans la liste ? Activez simplement l'interrupteur à sa droite.",
  "开启后若仍无法采集，请回到 Mote 重新启动。": "Si la collecte échoue toujours après activation, revenez dans Mote et redémarrez-la.",
  "仅在所选文件夹无法访问时开启；状态请在系统设置中确认。": "Activez-le uniquement si le dossier choisi reste inaccessible. Vérifiez son état dans les Réglages Système.",
