  "点击授权后，可将浮条中的应用拖入系统设置；列表中已有应用时，直接开启开关。": "Après avoir cliqué sur Donner l'accès, glissez l'app du bandeau dans les Réglages Système ; si elle y figure déjà, activez son interrupteur.",
